const GHAZAL_ITEMS = [{"id": "ghazal-1","num": 1,"kind": "Ghazal · #1","firstLine": "अगरचे थे तो दोनों ही ग़लत अल्लाह जाने है","versesHtml": ["<div class=\"verse\"><span class=\"line\">अगरचे थे तो दोनों ही ग़लत अल्लाह जाने है</span><span class=\"line\">मगर बस इक ने क्यूँ की मा'ज़रत अल्लाह जाने है</span></div>","<div class=\"verse\"><span class=\"line\">करे है पाक ज़ाहिर को कि दुनिया तुझ को समझे नेक</span><span class=\"line\">मियाँ बातिन का क्या जिस को फ़क़त अल्लाह जाने है</span></div>","<div class=\"verse\"><span class=\"line\">अगर तनक़ीद करती है तिरे किरदार पर दुनिया</span><span class=\"line\">न हो मायूस तेरी असलियत अल्लाह जाने है</span></div>","<div class=\"verse\"><span class=\"line\">बशर तो फ़ितरतन माने है मुश्किल को 'अज़ाब अपना</span><span class=\"line\">पर उस मुश्किल में जो है 'आफ़ियत अल्लाह जाने है</span></div>","<div class=\"verse\"><span class=\"line\">न हो ग़म बाँटने को कोई गर तो मुतमइन यूँ रह</span><span class=\"line\">कि है अल्लाह और हर कैफ़ियत अल्लाह जाने है</span></div>","<div class=\"verse\"><span class=\"line\">तू इतना सोच मत मंज़िल को आग़ाज़-ए-सफ़र में ही</span><span class=\"line\">तू बस चल पड़ कि रस्ते अन-गिनत अल्लाह जाने है</span></div>","<div class=\"verse\"><span class=\"line\">यहाँ हर शख़्स ख़ुद को लाइक़-ए-बख़्शिश समझता है</span><span class=\"line\">मगर सँवरेगी किस की आख़िरत अल्लाह जाने है</span></div>","<div class=\"verse\"><span class=\"line\">नहीं था बे-सबब उस शख़्स का तुझ से बिछड़ना 'ज़ान'</span><span class=\"line\">नहीं थी उस को तेरी अहमियत अल्लाह जाने है</span></div>"],"versesHtmlEn": ["<div class=\"verse\"><span class=\"line\">Agarche the to dono hi ghalat allah jaane hai</span><span class=\"line\">Magar bas ik ne kyun ki maa'zarat allah jaane hai</span></div>","<div class=\"verse\"><span class=\"line\">Kare hai paak zaahir ko ki duniya tujh ko samjhe nek</span><span class=\"line\">Miyaan baatin ka kya jis ko faqat allah jaane hai</span></div>","<div class=\"verse\"><span class=\"line\">Agar tanqeed karti hai tire kirdaar par duniya</span><span class=\"line\">Na ho mayoos teri asliyat allah jaane hai</span></div>","<div class=\"verse\"><span class=\"line\">Bashar to fitratan maane hai mushkil ko 'azaab apna</span><span class=\"line\">Par us mushkil mein jo hai 'aafiyat allah jaane hai</span></div>","<div class=\"verse\"><span class=\"line\">Na ho gham baantne ko koi gar to mutmain yun rah</span><span class=\"line\">Ki hai allah aur har kaifiyat allah jaane hai</span></div>","<div class=\"verse\"><span class=\"line\">Tu itna soch mat manzil ko aaghaz-e-safar mein hi</span><span class=\"line\">Tu bas chal pad ki raste an-ginat allah jaane hai</span></div>","<div class=\"verse\"><span class=\"line\">Yahaan har shakhs khud ko laayaq-e-bakhshish samajhta hai</span><span class=\"line\">Magar sanvaregi kis ki aakhirat allah jaane hai</span></div>","<div class=\"verse\"><span class=\"line\">Nahin tha be-sabab us shakhs ka tujh se bichhadna 'Zaan'</span><span class=\"line\">Nahin thi us ko teri ahamiyat allah jaane hai</span></div>"],"firstLineEn": "Agarche the to dono hi ghalat allah jaane hai"},{"id": "ghazal-2","num": 2,"kind": "Ghazal · #2","firstLine": "सोच रक्खा था मैं ने भी क्या क्या नहीं","versesHtml": ["<div class=\"verse\"><span class=\"line\">सोच रक्खा था मैं ने भी क्या क्या नहीं</span><span class=\"line\">सोचने भर से पर कुछ भी होता नहीं</span></div>","<div class=\"verse\"><span class=\"line\">गर जो चाहूँ तो कर लूँ दुबारा ये 'इश्क़</span><span class=\"line\">पर मैं अब जोश में होश खोता नहीं</span></div>","<div class=\"verse\"><span class=\"line\">ख़ामुशी, बे-कली, बे-हिसी, तेरी याद</span><span class=\"line\">और ऊपर से मौसम भी अच्छा नहीं</span></div>","<div class=\"verse\"><span class=\"line\">अब भी खुश-बू है याँ उस के अन्फ़ास की</span><span class=\"line\">हाँ वो शायद बिछड़ कर भी बिछड़ा नहीं</span></div>","<div class=\"verse\"><span class=\"line\">लर्ज़िश-ए-दस्त-ओ-पा, चश्म-ए-नम, भारी मन</span><span class=\"line\">'इश्क़ की इंतिहा में कुछ अच्छा नहीं</span></div>","<div class=\"verse\"><span class=\"line\">था गवारा तुझे मुझ को खोना तो जा</span><span class=\"line\">तुझ को पाना मुझे अब गवारा नहीं</span></div>","<div class=\"verse\"><span class=\"line\">अब तो रग़बत नहीं शा'इरी से भी 'ज़ान'</span><span class=\"line\">अब मिरे ग़म का कोई मुदावा नहीं</span></div>"],"versesHtmlEn": ["<div class=\"verse\"><span class=\"line\">Soch rakkha tha main ne bhi kya kya nahin</span><span class=\"line\">Sochne bhar se par kuchh bhi hota nahin</span></div>","<div class=\"verse\"><span class=\"line\">Gar jo chaahun to kar lun dubaara ye 'ishq</span><span class=\"line\">Par main ab josh mein hosh khota nahin</span></div>","<div class=\"verse\"><span class=\"line\">Khaamushi, be-kali, be-hisi, teri yaad</span><span class=\"line\">Aur upar se mausam bhi achchha nahin</span></div>","<div class=\"verse\"><span class=\"line\">Ab bhi khush-boo hai yaan us ke anfaas ki</span><span class=\"line\">Haan wo shaayad bichhad kar bhi bichhda nahin</span></div>","<div class=\"verse\"><span class=\"line\">Larzish-e-dast-o-pa, chashm-e-nam, bhaari man</span><span class=\"line\">'Ishq ki intiha mein kuchh achchha nahin</span></div>","<div class=\"verse\"><span class=\"line\">Tha gawaara tujhe mujh ko khona to ja</span><span class=\"line\">Tujh ko paana mujhe ab gawaara nahin</span></div>","<div class=\"verse\"><span class=\"line\">Ab to raghbat nahin shaa'iri se bhi 'Zaan'</span><span class=\"line\">Ab mire gham ka koi mudaawa nahin</span></div>"],"firstLineEn": "Soch rakkha tha main ne bhi kya kya nahin"},{"id": "ghazal-3","num": 3,"kind": "Ghazal · #3","firstLine": "इस क़दर जीना मिरा मुश्किल न होता","versesHtml": ["<div class=\"verse\"><span class=\"line\">इस क़दर जीना मिरा मुश्किल न होता</span><span class=\"line\">काश या अल्लाह मुझ में दिल न होता</span></div>","<div class=\"verse\"><span class=\"line\">हम-सफ़र बिछड़ा न होता गर सर-ए-राह</span><span class=\"line\">मैं अभी शायद सर-ए-मंज़िल न होता</span></div>","<div class=\"verse\"><span class=\"line\">गर पता होता कि वो हासिल न होगा</span><span class=\"line\">बा-ख़ुदा मैं भी उसे हासिल न होता</span></div>","<div class=\"verse\"><span class=\"line\">ग़ौर से अब सोचता हूँ जो हुआ था</span><span class=\"line\">क्या वो होता मैं अगर ग़ाफ़िल न होता</span></div>","<div class=\"verse\"><span class=\"line\">बस में होता तो बनाता इक नया दहर</span><span class=\"line\">जिस में मैं तेरी तरफ़ माइल न होता</span></div>","<div class=\"verse\"><span class=\"line\">क़ुफ़्ल गर होता दर-ए-दिल में वफ़ा का</span><span class=\"line\">जुज़ पिया के कोई भी दाख़िल न होता</span></div>","<div class=\"verse\"><span class=\"line\">होता तू महफ़िल का मौज़ू'-ए-सुख़न 'ज़ान'</span><span class=\"line\">हाँ अगर तू दर-ख़ुर-ए-महफ़िल न होता</span></div>"],"versesHtmlEn": ["<div class=\"verse\"><span class=\"line\">Is qadar jeena mira mushkil na hota</span><span class=\"line\">Kaash ya allah mujh mein dil na hota</span></div>","<div class=\"verse\"><span class=\"line\">Hum-safar bichhda na hota gar sar-e-raah</span><span class=\"line\">Main abhi shaayad sar-e-manzil na hota</span></div>","<div class=\"verse\"><span class=\"line\">Gar pata hota ki wo haasil na hoga</span><span class=\"line\">Ba-khuda main bhi use haasil na hota</span></div>","<div class=\"verse\"><span class=\"line\">Ghaur se ab sochta hun jo hua tha</span><span class=\"line\">Kya wo hota main agar ghaafil na hota</span></div>","<div class=\"verse\"><span class=\"line\">Bas mein hota to banaata ik naya dahr</span><span class=\"line\">Jis mein main teri taraf maail na hota</span></div>","<div class=\"verse\"><span class=\"line\">Qufl gar hota dar-e-dil mein wafa ka</span><span class=\"line\">Juz piya ke koi bhi daakhil na hota</span></div>","<div class=\"verse\"><span class=\"line\">Hota tu mahfil ka mauzoo'-e-sukhan 'Zaan'</span><span class=\"line\">Haan agar tu dar-khur-e-mahfil na hota</span></div>"],"firstLineEn": "Is qadar jeena mira mushkil na hota"},{"id": "ghazal-4","num": 4,"kind": "Ghazal · #4","firstLine": "तू जब बा'द-ए-तर्क-ए-त'अल्लुक़ बहुत ख़ुश दिखा तब लगा","versesHtml": ["<div class=\"verse\"><span class=\"line\">तू जब बा'द-ए-तर्क-ए-त'अल्लुक़ बहुत ख़ुश दिखा तब लगा</span><span class=\"line\">कि गोया तिरी ज़ीस्त का अब तलक मसअला मैं ही था</span></div>","<div class=\"verse\"><span class=\"line\">हुआ था जो माज़ी में उस से न कर रोज़-ए-फ़र्दा ख़राब</span><span class=\"line\">बहुत कुछ हुआ था मगर क्या हुआ जो हुआ सो हुआ</span></div>","<div class=\"verse\"><span class=\"line\">ये मासूम दिल मेरा अब भी तलाशे है गुंजाइशें</span><span class=\"line\">भले ज़ेहन माने कि वो दास्ताँ हो चुकी है फ़ना</span></div>","<div class=\"verse\"><span class=\"line\">गँवा एक दूजे को दोनो ने पाया ही है कुछ न कुछ</span><span class=\"line\">किसी को नया हम-सफ़र मिल गया तो किसी को ख़ुदा</span></div>","<div class=\"verse\"><span class=\"line\">मैं ये देख कर ही तो ख़ुश हूँ कि मैं उन की सोचों में हूँ</span><span class=\"line\">फिर अब वो सताइश करें या बुराई मुझे उस से क्या</span></div>","<div class=\"verse\"><span class=\"line\">मलाल इस का कब था कि 'अहद-ए-वफ़ा उस ने तोड़ा था 'ज़ान'</span><span class=\"line\">नदामत तो ये थी मैं सब जान कर भी निभाता रहा</span></div>"],"versesHtmlEn": ["<div class=\"verse\"><span class=\"line\">Tu jab baa'd-e-tark-e-ta'alluq bahut khush dikha tab laga</span><span class=\"line\">Ki goya tiri zeest ka ab talak mas'ala main hi tha</span></div>","<div class=\"verse\"><span class=\"line\">Hua tha jo maazi mein us se na kar roz-e-farda kharaab</span><span class=\"line\">Bahut kuchh hua tha magar kya hua jo hua so hua</span></div>","<div class=\"verse\"><span class=\"line\">Ye maasoom dil mera ab bhi talaashe hai gunjaaishen</span><span class=\"line\">Bhale zehan maane ki wo daastaan ho chuki hai fana</span></div>","<div class=\"verse\"><span class=\"line\">Ganva ek dooje ko dono ne paaya hi hai kuchh na kuchh</span><span class=\"line\">Kisi ko naya hum-safar mil gaya to kisi ko khuda</span></div>","<div class=\"verse\"><span class=\"line\">Main ye dekh kar hi to khush hun ki main un ki sochon mein hun</span><span class=\"line\">Phir ab wo sataaish karen ya buraai mujhe us se kya</span></div>","<div class=\"verse\"><span class=\"line\">Malaal is ka kab tha ki 'ahd-e-wafa us ne toda tha 'Zaan'</span><span class=\"line\">Nadaamat to ye thi main sab jaan kar bhi nibhaata raha</span></div>"],"firstLineEn": "Tu jab baa'd-e-tark-e-ta'alluq bahut khush dikha tab laga"},{"id": "ghazal-5","num": 5,"kind": "Ghazal · #5","firstLine": "गाह दरिया रहे गाह सहरा रहे","versesHtml": ["<div class=\"verse\"><span class=\"line\">गाह दरिया रहे गाह सहरा रहे</span><span class=\"line\">कोई उस से कहो एक जैसा रहे</span></div>","<div class=\"verse\"><span class=\"line\">ऐ मिरे दिल बता ये ज़रूरी है क्या</span><span class=\"line\">जो हमेशा से था वो हमेशा रहे</span></div>","<div class=\"verse\"><span class=\"line\">जिन के किरदार अच्छे रहे 'उम्र भर</span><span class=\"line\">ख़ूब बाद-ए-फ़ना भी वो ज़िंदा रहे</span></div>","<div class=\"verse\"><span class=\"line\">तुम तो उन की ही बोली लगे बोलने</span><span class=\"line\">साथ उन के मियाँ चार दिन क्या रहे</span></div>","<div class=\"verse\"><span class=\"line\">ख़्वाहिशों के लिए आख़िरी दम तलक</span><span class=\"line\">चाहिए आदमी को कि लड़ता रहे</span></div>","<div class=\"verse\"><span class=\"line\">मर गया 'इश्क़ अगर दुश्मनी ही सही</span><span class=\"line\">कम से कम तुझ से कोई तो रिश्ता रहे</span></div>","<div class=\"verse\"><span class=\"line\">सब को समझा के मैं थक चुका हूँ सो अब</span><span class=\"line\">जो समझना है जिस को समझता रहे</span></div>","<div class=\"verse\"><span class=\"line\">कोई कैसे ही पाए है याँ ग़म-गुसार</span><span class=\"line\">'ज़ान' हम तो सदा ग़म में तन्हा रहे</span></div>"],"versesHtmlEn": ["<div class=\"verse\"><span class=\"line\">Gaah dariya rahe gaah sahra rahe</span><span class=\"line\">Koi us se kaho ek jaisa rahe</span></div>","<div class=\"verse\"><span class=\"line\">Ai mire dil bata ye zaroori hai kya</span><span class=\"line\">Jo hamesha se tha wo hamesha rahe</span></div>","<div class=\"verse\"><span class=\"line\">Jin ke kirdaar achchhe rahe 'umr bhar</span><span class=\"line\">Khoob baad-e-fana bhi wo zinda rahe</span></div>","<div class=\"verse\"><span class=\"line\">Tum to un ki hi boli lage bolne</span><span class=\"line\">Saath un ke miyaan chaar din kya rahe</span></div>","<div class=\"verse\"><span class=\"line\">Khwaahishon ke liye aakhiri dam talak</span><span class=\"line\">Chaahiye aadmi ko ki ladta rahe</span></div>","<div class=\"verse\"><span class=\"line\">Mar gaya 'ishq agar dushmani hi sahi</span><span class=\"line\">Kam se kam tujh se koi to rishta rahe</span></div>","<div class=\"verse\"><span class=\"line\">Sab ko samjha ke main thak chuka hun so ab</span><span class=\"line\">Jo samajhna hai jis ko samajhta rahe</span></div>","<div class=\"verse\"><span class=\"line\">Koi kaise hi paaye hai yaan gham-gusaar</span><span class=\"line\">'Zaan' hum to sada gham mein tanha rahe</span></div>"],"firstLineEn": "Gaah dariya rahe gaah sahra rahe"},{"id": "ghazal-6","num": 6,"kind": "Ghazal · #6","firstLine": "मैं पिछली मोहब्बत की शिद्दत का मारा ज़रा एहतियात अब ज़ियादा करूँगा","versesHtml": ["<div class=\"verse\"><span class=\"line\">मैं पिछली मोहब्बत की शिद्दत का मारा ज़रा एहतियात अब ज़ियादा करूँगा</span><span class=\"line\">कि शायद ही अब उस क़दर दिल को अपने किसी के लिए मैं कुशादा करूँगा</span></div>","<div class=\"verse\"><span class=\"line\">अभी कल ही मैं ने इरादा किया था कि बस अब मैं उस को भुला दूँगा यक्सर</span><span class=\"line\">पर आज उस को फिर याद करने लगा हूँ सो हाँ आज फिर से इरादा करूँगा</span></div>","<div class=\"verse\"><span class=\"line\">मुझे इस ज़माने के 'आशिक़ बताएँ कि क्या इतना कमज़ोर है 'इश्क़ अब का</span><span class=\"line\">कि ये 'इश्क़ पुख़्ता तभी होगा जब मैं पिया का बदन बे-लिबादा करूँगा</span></div>","<div class=\"verse\"><span class=\"line\">अगरचे मैं पुर-हौसला तो बहुत हूँ मगर अपनी क़िस्मत से वाक़िफ़ भी हूँ मैं</span><span class=\"line\">सो मुझ को न यूँ हार ही माननी है न मैं जीत जाने का वा'दा करूँगा</span></div>","<div class=\"verse\"><span class=\"line\">मुझे तेरे होने न होने से क्या है तू जान-ए-ग़ज़ल थी मिरी और रहेगी</span><span class=\"line\">कभी वस्ल से काम लेता था तेरे और अब हिज्र से इस्तिफ़ादा करूँगा</span></div>"],"versesHtmlEn": ["<div class=\"verse\"><span class=\"line\">Main pichhli mohabbat ki shiddat ka maara zara ehtiyaat ab zyaada karunga</span><span class=\"line\">Ki shaayad hi ab us qadar dil ko apne kisi ke liye main kushaada karunga</span></div>","<div class=\"verse\"><span class=\"line\">Abhi kal hi main ne iraada kiya tha ki bas ab main us ko bhula dunga yaksar</span><span class=\"line\">Par aaj us ko phir yaad karne laga hun so haan aaj phir se iraada karunga</span></div>","<div class=\"verse\"><span class=\"line\">Mujhe is zamaane ke 'aashiq bataaen ki kya itna kamzor hai 'ishq ab ka</span><span class=\"line\">Ki ye 'ishq pukhta tabhi hoga jab main piya ka badan be-libaada karunga</span></div>","<div class=\"verse\"><span class=\"line\">Agarche main pur-hausla to bahut hun magar apni qismat se waaqif bhi hun main</span><span class=\"line\">So mujhe na yun haar hi maanni hai na main jeet jaane ka wa'da karunga</span></div>","<div class=\"verse\"><span class=\"line\">Mujhe tere hone na hone se kya hai tu jaan-e-ghazal thi miri aur rahegi</span><span class=\"line\">Kabhi wasl se kaam leta tha tere aur ab hijr se istifaada karunga</span></div>"],"firstLineEn": "Main pichhli mohabbat ki shiddat ka maara zara ehtiyaat ab zyaada karunga"},{"id": "ghazal-7","num": 7,"kind": "Ghazal · #7","firstLine": "तू है जिस को यूँ मुयस्सर, कौन है","versesHtml": ["<div class=\"verse\"><span class=\"line\">तू है जिस को यूँ मुयस्सर, कौन है</span><span class=\"line\">वो मुक़द्दर का सिकंदर कौन है</span></div>","<div class=\"verse\"><span class=\"line\">तेरी आँखों में मिरी तस्वीर नइं</span><span class=\"line\">बोल क़ाबिज़ तेरे दिल पर कौन है</span></div>","<div class=\"verse\"><span class=\"line\">ज़ुल्म पर चुप रहने वाले ख़ुद से पूछ</span><span class=\"line\">अस्ल में तेरा सितमगर कौन है</span></div>","<div class=\"verse\"><span class=\"line\">देखना हो गर कोई दिलदार शख़्स</span><span class=\"line\">तो ये देखो ग़म का ख़ूगर कौन है</span></div>","<div class=\"verse\"><span class=\"line\">बस इसी में है तुम्हारी बेहतरी</span><span class=\"line\">सोचना मत तुम से बेहतर कौन है</span></div>","<div class=\"verse\"><span class=\"line\">जिस्म हो सकता नहीं उलफ़त की शर्त</span><span class=\"line\">आज कल ये मानता पर कौन है</span></div>","<div class=\"verse\"><span class=\"line\">मेरे बाहर मैं हूँ जो सब को दिखे</span><span class=\"line\">कौन जाने मेरे भीतर कौन है</span></div>","<div class=\"verse\"><span class=\"line\">जिस में जा मिलना है मुझ दरिया को 'ज़ान'</span><span class=\"line\">पूछना था वो समुंदर कौन है</span></div>"],"versesHtmlEn": ["<div class=\"verse\"><span class=\"line\">Tu hai jis ko yun muyassar, kaun hai</span><span class=\"line\">Wo muqaddar ka sikandar kaun hai</span></div>","<div class=\"verse\"><span class=\"line\">Teri aankhon mein miri tasveer nain</span><span class=\"line\">Bol qaabiz tere dil par kaun hai</span></div>","<div class=\"verse\"><span class=\"line\">Zulm par chup rahne waale khud se poochh</span><span class=\"line\">Asl mein tera sitamgar kaun hai</span></div>","<div class=\"verse\"><span class=\"line\">Dekhna ho gar koi dildaar shakhs</span><span class=\"line\">To ye dekho gham ka khoogar kaun hai</span></div>","<div class=\"verse\"><span class=\"line\">Bas isi mein hai tumhaari behatri</span><span class=\"line\">Sochna mat tum se behtar kaun hai</span></div>","<div class=\"verse\"><span class=\"line\">Jism ho sakta nahin ulfat ki shart</span><span class=\"line\">Aaj kal ye maanta par kaun hai</span></div>","<div class=\"verse\"><span class=\"line\">Mere baahar main hun jo sab ko dikhe</span><span class=\"line\">Kaun jaane mere bheetar kaun hai</span></div>","<div class=\"verse\"><span class=\"line\">Jis mein ja milna hai mujh dariya ko 'Zaan'</span><span class=\"line\">Poochhna tha wo samundar kaun hai</span></div>"],"firstLineEn": "Tu hai jis ko yun muyassar, kaun hai"},{"id": "ghazal-8","num": 8,"kind": "Ghazal · #8","firstLine": "भले न मिल मगर मुझे तू यूँ न दस्तियाब हो","versesHtml": ["<div class=\"verse\"><span class=\"line\">भले न मिल मगर मुझे तू यूँ न दस्तियाब हो</span><span class=\"line\">कि दिल को तेरे होते भी सुकूँ न दस्तियाब हो</span></div>","<div class=\"verse\"><span class=\"line\">ये वो जुनूँ है जिस में शाह भी गदागरी करे</span><span class=\"line\">मियाँ किसी को 'इश्क़ का जुनूँ न दस्तियाब हो</span></div>","<div class=\"verse\"><span class=\"line\">वही हुआ बिल-आख़िर उस ने तेरी क़द्र ही न की</span><span class=\"line\">तुझे कहा भी था उसे फ़ुज़ूँ न दस्तियाब हो</span></div>","<div class=\"verse\"><span class=\"line\">तिरी हर एक शय अज़ीज़ है सो है क़ुबूल भी</span><span class=\"line\">भले फ़क़त तिरा ये ग़म ही क्यूँ न दस्तियाब हो</span></div>","<div class=\"verse\"><span class=\"line\">तू क्या है उस को छोड़ कर उसी से चाहे है कि वो</span><span class=\"line\">किसी को तेरे बा'द जूँ का तूँ न दस्तियाब हो</span></div>"],"versesHtmlEn": ["<div class=\"verse\"><span class=\"line\">Bhale na mil magar mujhe tu yun na dastiyaab ho</span><span class=\"line\">Ki dil ko tere hote bhi sukoon na dastiyaab ho</span></div>","<div class=\"verse\"><span class=\"line\">Ye wo junoon hai jis mein shaah bhi gadaagari kare</span><span class=\"line\">Miyaan kisi ko 'ishq ka junoon na dastiyaab ho</span></div>","<div class=\"verse\"><span class=\"line\">Wahi hua bil-aakhir us ne teri qadr hi na ki</span><span class=\"line\">Tujhe kaha bhi tha use fuzoon na dastiyaab ho</span></div>","<div class=\"verse\"><span class=\"line\">Tiri har ek shay azeez hai so hai qubool bhi</span><span class=\"line\">Bhale faqat tira ye gham hi kyun na dastiyaab ho</span></div>","<div class=\"verse\"><span class=\"line\">Tu kya hai us ko chhod kar usi se chaahe hai ki wo</span><span class=\"line\">Kisi ko tere baa'd jun ka tun na dastiyaab ho</span></div>"],"firstLineEn": "Bhale na mil magar mujhe tu yun na dastiyaab ho"},{"id": "ghazal-9","num": 9,"kind": "Ghazal · #9","firstLine": "सज़ा के तौर पर पाई है ये बे-चारगी मैं ने","versesHtml": ["<div class=\"verse\"><span class=\"line\">सज़ा के तौर पर पाई है ये बे-चारगी मैं ने</span><span class=\"line\">गुनह ये था कि इक इंसान से उम्मीद की मैं ने</span></div>","<div class=\"verse\"><span class=\"line\">है इक ख़्वाहिश कि मुझ को भी कोई मेरी तरह चाहे</span><span class=\"line\">मिरे जैसा कोई 'आशिक़ नहीं देखा कभी मैं ने</span></div>","<div class=\"verse\"><span class=\"line\">वो जब तक था मिरी ख़ू-ए-फ़रामोशी भी तब तक थी</span><span class=\"line\">वो जब ख़ुद याद बन बैठा तो ये ख़ू छोड़ दी मैं ने</span></div>","<div class=\"verse\"><span class=\"line\">हुई मुद्दत कि आता भी नहीं है क़ब्र पर मेरी</span><span class=\"line\">वही इक शख़्स जिस पे वार दी थी ज़िंदगी मैं ने</span></div>","<div class=\"verse\"><span class=\"line\">'अदावत का कोई रिश्ता कभी होता नहीं है ख़त्म</span><span class=\"line\">इसी इक वज्ह से की है ग़मों से दोस्ती मैं ने</span></div>","<div class=\"verse\"><span class=\"line\">तो अब क्यूँ सोचता हूँ मैं मुसलसल उस के बारे में</span><span class=\"line\">अगर वो बात क़स्दन ही करी थी अन-सुनी मैं ने</span></div>","<div class=\"verse\"><span class=\"line\">नज़र जब तक न आया वो करी तब तक तलाश उस की</span><span class=\"line\">मगर जब वो नज़र आया नज़र ही फेर ली मैं ने</span></div>","<div class=\"verse\"><span class=\"line\">बहुत कमज़ोर लम्हे पेश आए ज़िंदगी में 'ज़ान'</span><span class=\"line\">पर उन कमज़ोर लम्हों में बहुत की शायरी मैं ने</span></div>"],"versesHtmlEn": ["<div class=\"verse\"><span class=\"line\">Saza ke taur par paai hai ye be-chaargi main ne</span><span class=\"line\">Gunah ye tha ki ik insaan se ummeed ki main ne</span></div>","<div class=\"verse\"><span class=\"line\">Hai ik khwaahish ki mujh ko bhi koi meri tarah chaahe</span><span class=\"line\">Mire jaisa koi 'aashiq nahin dekha kabhi main ne</span></div>","<div class=\"verse\"><span class=\"line\">Wo jab tak tha miri khoo-e-faraamoshi bhi tab tak thi</span><span class=\"line\">Wo jab khud yaad ban baitha to ye khoo chhod di main ne</span></div>","<div class=\"verse\"><span class=\"line\">Hui muddat ki aata bhi nahin hai qabr par meri</span><span class=\"line\">Wahi ik shakhs jis pe waar di thi zindagi main ne</span></div>","<div class=\"verse\"><span class=\"line\">'Adaawat ka koi rishta kabhi hota nahin hai khatm</span><span class=\"line\">Isi ik wajh se ki hai ghamon se dosti main ne</span></div>","<div class=\"verse\"><span class=\"line\">To ab kyun sochta hun main musalsal us ke baare mein</span><span class=\"line\">Agar wo baat qasdan hi kari thi an-suni main ne</span></div>","<div class=\"verse\"><span class=\"line\">Nazar jab tak na aaya wo kari tab tak talaash us ki</span><span class=\"line\">Magar jab wo nazar aaya nazar hi pher li main ne</span></div>","<div class=\"verse\"><span class=\"line\">Bahut kamzor lamhe pesh aae zindagi mein 'Zaan'</span><span class=\"line\">Par un kamzor lamhon mein bahut ki shaayari main ne</span></div>"],"firstLineEn": "Saza ke taur par paai hai ye be-chaargi main ne"},{"id": "ghazal-10","num": 10,"kind": "Ghazal · #10","firstLine": "सदा इस ने मुझे हिम्मत फ़राहम की","versesHtml": ["<div class=\"verse\"><span class=\"line\">सदा इस ने मुझे हिम्मत फ़राहम की</span><span class=\"line\">यही इक बात है अच्छी मिरे ग़म की</span></div>","<div class=\"verse\"><span class=\"line\">ख़िज़ाँ की रुत का सूखा गुल समझ मुझ को</span><span class=\"line\">अगर तू है घटा सावन के मौसम की</span></div>","<div class=\"verse\"><span class=\"line\">अब उस के बा'द इन ज़ख़्मों से कैसा बैर</span><span class=\"line\">वो जब मरहम था तब हाजत थी मरहम की</span></div>","<div class=\"verse\"><span class=\"line\">तिरे पैकर को छूने की है मुझ को चाह</span><span class=\"line\">बड़ी दिल-चस्प है आग इस जहन्नम की</span></div>","<div class=\"verse\"><span class=\"line\">नवाज़िश जिन गुलों पर बाग़बाँ की हो</span><span class=\"line\">उन्हें क्या अहमियत क़तरा-ए-शबनम की</span></div>","<div class=\"verse\"><span class=\"line\">अलम था दाइमी सो इस पे क्या रोते</span><span class=\"line\">ख़ुशी जब भी मिली तो आँख पुर-नम की</span></div>","<div class=\"verse\"><span class=\"line\">फ़रिश्तों सा समझता है ये ख़ुद को 'ज़ान'</span><span class=\"line\">यही तो है ख़राबी इब्न-ए-आदम की</span></div>"],"versesHtmlEn": ["<div class=\"verse\"><span class=\"line\">Sada is ne mujhe himmat faraaham ki</span><span class=\"line\">Yahi ik baat hai achchhi mire gham ki</span></div>","<div class=\"verse\"><span class=\"line\">Khizaan ki rut ka sookha gul samajh mujh ko</span><span class=\"line\">Agar tu hai ghata saawan ke mausam ki</span></div>","<div class=\"verse\"><span class=\"line\">Ab us ke baa'd in zakhmon se kaisa bair</span><span class=\"line\">Wo jab marham tha tab haajat thi marham ki</span></div>","<div class=\"verse\"><span class=\"line\">Tire paikar ko chhoone ki hai mujh ko chaah</span><span class=\"line\">Badi dil-chasp hai aag is jahannam ki</span></div>","<div class=\"verse\"><span class=\"line\">Nawaazish jin gulon par baaghbaan ki ho</span><span class=\"line\">Unhen kya ahamiyat qatra-e-shabnam ki</span></div>","<div class=\"verse\"><span class=\"line\">Alam tha daaimi so is pe kya rote</span><span class=\"line\">Khushi jab bhi mili to aankh pur-nam ki</span></div>","<div class=\"verse\"><span class=\"line\">Farishton sa samajhta hai ye khud ko 'Zaan'</span><span class=\"line\">Yahi to hai kharaabi ibn-e-aadam ki</span></div>"],"firstLineEn": "Sada is ne mujhe himmat faraaham ki"},{"id": "ghazal-11","num": 11,"kind": "Ghazal · #11","firstLine": "कम-अज़-कम छोड़ देते मुझ को मेरे साथ","versesHtml": ["<div class=\"verse\"><span class=\"line\">कम-अज़-कम छोड़ देते मुझ को मेरे साथ</span><span class=\"line\">गए तो ले गए सब कुछ तुम अपने साथ</span></div>","<div class=\"verse\"><span class=\"line\">हमें वो लोग यक्सर भूल जाते हैं</span><span class=\"line\">बहुत यादें बनी होती हैं जिन के साथ</span></div>","<div class=\"verse\"><span class=\"line\">तो क्या इक दूसरे को छोड़ कर हम ने</span><span class=\"line\">बहुत अच्छा किया इक दूसरे के साथ</span></div>","<div class=\"verse\"><span class=\"line\">उन्हें अब याद करने से उड़े है चैन</span><span class=\"line\">वो पल जो चैन से काटे थे हम ने साथ</span></div>","<div class=\"verse\"><span class=\"line\">मिरी तन्हाई को लोगों से क्या मतलब</span><span class=\"line\">भरी महफ़िल में भी रहती है मेरे साथ</span></div>","<div class=\"verse\"><span class=\"line\">अभी भी साथ हैं तालाब में वो हंस</span><span class=\"line\">भला होता अगर तुम भी निभाते साथ</span></div>","<div class=\"verse\"><span class=\"line\">मैं तन्हा चलने से क़ासिर नहीं पर काश</span><span class=\"line\">कोई होता जो चलता हर क़दम पे साथ</span></div>","<div class=\"verse\"><span class=\"line\">जब आया तन्हा और जाएगा भी तन्हा</span><span class=\"line\">तो फिर क्यूँ 'ज़ान' जीते जी न माँगे साथ</span></div>"],"versesHtmlEn": ["<div class=\"verse\"><span class=\"line\">Kam-az-kam chhod dete mujh ko mere saath</span><span class=\"line\">Gae to le gae sab kuchh tum apne saath</span></div>","<div class=\"verse\"><span class=\"line\">Hamen wo log yaksar bhool jaate hain</span><span class=\"line\">Bahut yaaden bani hoti hain jin ke saath</span></div>","<div class=\"verse\"><span class=\"line\">To kya ik dusre ko chhod kar hum ne</span><span class=\"line\">Bahut achchha kiya ik dusre ke saath</span></div>","<div class=\"verse\"><span class=\"line\">Unhen ab yaad karne se ude hai chain</span><span class=\"line\">Wo pal jo chain se kaate the hum ne saath</span></div>","<div class=\"verse\"><span class=\"line\">Miri tanhaai ko logon se kya matlab</span><span class=\"line\">Bhari mahfil mein bhi rahti hai mere saath</span></div>","<div class=\"verse\"><span class=\"line\">Abhi bhi saath hain taalaab mein wo hans</span><span class=\"line\">Bhala hota agar tum bhi nibhaate saath</span></div>","<div class=\"verse\"><span class=\"line\">Main tanha chalne se qaasir nahin par kaash</span><span class=\"line\">Koi hota jo chalta har qadam pe saath</span></div>","<div class=\"verse\"><span class=\"line\">Jab aaya tanha aur jaaega bhi tanha</span><span class=\"line\">To phir kyun 'Zaan' jeete ji na maange saath</span></div>"],"firstLineEn": "Kam-az-kam chhod dete mujh ko mere saath"},{"id": "ghazal-12","num": 12,"kind": "Ghazal · #12","firstLine": "तुझे हो मुबारक तिरी बे-वफ़ाई","versesHtml": ["<div class=\"verse\"><span class=\"line\">तुझे हो मुबारक तिरी बे-वफ़ाई</span><span class=\"line\">मैं ख़ुश हूँ कि मैं ने मोहब्बत निभाई</span></div>","<div class=\"verse\"><span class=\"line\">तुम्हारा त'अल्लुक़ है इक नेक घर से</span><span class=\"line\">तुम्हें ज़ेब देती नहीं बे-हयाई</span></div>","<div class=\"verse\"><span class=\"line\">मिरा दिल दुखा भी तो क्या ग़म कम-अज़-कम</span><span class=\"line\">असीर-ए-मोहब्बत ने पाई रिहाई</span></div>","<div class=\"verse\"><span class=\"line\">नया 'इश्क़ कर या मना पिछले का ग़म</span><span class=\"line\">कुआँ तेरे आगे है पीछे है खाई</span></div>","<div class=\"verse\"><span class=\"line\">रहे दोस्ती बा'द-ए-तर्क-ए-मोहब्बत</span><span class=\"line\">ये बात आप की रास मुझ को न आई</span></div>","<div class=\"verse\"><span class=\"line\">जो मंज़र नहीं देखना चाहता मैं</span><span class=\"line\">वही मुझ को देता है अक्सर दिखाई</span></div>","<div class=\"verse\"><span class=\"line\">ज़माना मुझे गर बुरा कह रहा है</span><span class=\"line\">ज़माने की होगी इसी में भलाई</span></div>","<div class=\"verse\"><span class=\"line\">वो सब्र आज़माए करम करने से क़ब्ल</span><span class=\"line\">बहुत बार मैं ने ये बात आज़माई</span></div>","<div class=\"verse\"><span class=\"line\">उदास आज था मैं सदा की तरह 'ज़ान'</span><span class=\"line\">सदा की तरह फिर ग़ज़ल गुनगुनाई</span></div>"],"versesHtmlEn": ["<div class=\"verse\"><span class=\"line\">Tujhe ho mubaarak tiri be-wafaai</span><span class=\"line\">Main khush hun ki main ne mohabbat nibhaai</span></div>","<div class=\"verse\"><span class=\"line\">Tumhaara ta'alluq hai ik nek ghar se</span><span class=\"line\">Tumhen zeb deti nahin be-hayaai</span></div>","<div class=\"verse\"><span class=\"line\">Mira dil dukha bhi to kya gham kam-az-kam</span><span class=\"line\">Aseer-e-mohabbat ne paai rihaai</span></div>","<div class=\"verse\"><span class=\"line\">Naya 'ishq kar ya mana pichhle ka gham</span><span class=\"line\">Kuaan tere aage hai peechhe hai khaai</span></div>","<div class=\"verse\"><span class=\"line\">Rahe dosti baa'd-e-tark-e-mohabbat</span><span class=\"line\">Ye baat aap ki raas mujh ko na aai</span></div>","<div class=\"verse\"><span class=\"line\">Jo manzar nahin dekhna chaahta main</span><span class=\"line\">Wahi mujh ko deta hai aksar dikhaai</span></div>","<div class=\"verse\"><span class=\"line\">Zamaana mujhe gar bura kah raha hai</span><span class=\"line\">Zamaane ki hogi isi mein bhalaai</span></div>","<div class=\"verse\"><span class=\"line\">Wo sabr aazmaae karam karne se qabl</span><span class=\"line\">Bahut baar main ne ye baat aazmaai</span></div>","<div class=\"verse\"><span class=\"line\">Udaas aaj tha main sada ki tarah 'Zaan'</span><span class=\"line\">Sada ki tarah phir ghazal gungunaai</span></div>"],"firstLineEn": "Tujhe ho mubaarak tiri be-wafaai"},{"id": "ghazal-13","num": 13,"kind": "Ghazal · #13","firstLine": "चाहता हूँ तिरे हर सितम की मुकाफ़ात हो","versesHtml": ["<div class=\"verse\"><span class=\"line\">चाहता हूँ तिरे हर सितम की मुकाफ़ात हो</span><span class=\"line\">जो मिरे साथ तू ने किया कल तिरे साथ हो</span></div>","<div class=\"verse\"><span class=\"line\">रोज़ जब सुब्ह उठता हूँ होता है मन यूँ उदास</span><span class=\"line\">गोया तेरा बिछड़ना अभी कल ही की बात हो</span></div>","<div class=\"verse\"><span class=\"line\">अपनी ख़ल्वत को ज़ाया न कर ये ख़ुदा की है देन</span><span class=\"line\">ता कि तन्हाई में तेरी तुझ से मुलाक़ात हो</span></div>","<div class=\"verse\"><span class=\"line\">और आसान हो ता कि अगली दफ़ा जीतना</span><span class=\"line\">मात हो ही रही है तो अच्छी तरह मात हो</span></div>","<div class=\"verse\"><span class=\"line\">पूरे दिन का थका जिस्म है रात का मुंतज़िर</span><span class=\"line\">और ये दिल कि जो चाहता ही नहीं रात हो</span></div>","<div class=\"verse\"><span class=\"line\">महफ़िल-ए-ग़ैर में मेरी रुस्वाई के पीछे भी</span><span class=\"line\">कुछ त'अज्जुब नहीं गर मिरे अपनों का हाथ हो</span></div>","<div class=\"verse\"><span class=\"line\">फिर ही शायद इन आँखों में क़ौस-ए-क़ुज़ह हो 'अयाँ</span><span class=\"line\">'ज़ान' मुमकिन है पहले इन आँखों से बरसात हो</span></div>"],"versesHtmlEn": ["<div class=\"verse\"><span class=\"line\">Chaahta hun tire har sitam ki mukaafaat ho</span><span class=\"line\">Jo mire saath tu ne kiya kal tire saath ho</span></div>","<div class=\"verse\"><span class=\"line\">Roz jab subh uthta hun hota hai man yun udaas</span><span class=\"line\">Goya tera bichhadna abhi kal hi ki baat ho</span></div>","<div class=\"verse\"><span class=\"line\">Apni khalwat ko zaaya na kar ye khuda ki hai den</span><span class=\"line\">Ta ki tanhaai mein teri tujh se mulaaqaat ho</span></div>","<div class=\"verse\"><span class=\"line\">Aur aasaan ho ta ki agli dafa jeetna</span><span class=\"line\">Maat ho hi rahi hai to achchhi tarah maat ho</span></div>","<div class=\"verse\"><span class=\"line\">Poore din ka thaka jism hai raat ka muntazir</span><span class=\"line\">Aur ye dil ki jo chaahta hi nahin raat ho</span></div>","<div class=\"verse\"><span class=\"line\">Mahfil-e-ghair mein meri ruswaai ke peechhe bhi</span><span class=\"line\">Kuchh ta'ajjub nahin gar mire apnon ka haath ho</span></div>","<div class=\"verse\"><span class=\"line\">Phir hi shaayad in aankhon mein qaus-e-quzah ho 'ayaan</span><span class=\"line\">'Zaan' mumkin hai pahle in aankhon se barsaat ho</span></div>"],"firstLineEn": "Chaahta hun tire har sitam ki mukaafaat ho"},{"id": "ghazal-14","num": 14,"kind": "Ghazal · #14","firstLine": "सुकून इस दर्जा फ़ुर्क़त में नहीं होता","versesHtml": ["<div class=\"verse\"><span class=\"line\">सुकून इस दर्जा फ़ुर्क़त में नहीं होता</span><span class=\"line\">अगर ये ज़ेहन ग़फ़लत में नहीं होता</span></div>","<div class=\"verse\"><span class=\"line\">वो सब कुछ पा के भी अक्सर रहे बे-चैन</span><span class=\"line\">तशक्कुर जिस की फ़ितरत में नहीं होता</span></div>","<div class=\"verse\"><span class=\"line\">मदद माँगे कोई तो बे झिझक करना</span><span class=\"line\">ख़सारा इस तिजारत में नहीं होता</span></div>","<div class=\"verse\"><span class=\"line\">मगर क्या क्या नहीं होता तसव्वुर में</span><span class=\"line\">अगरचे कुछ हक़ीक़त में नहीं होता</span></div>","<div class=\"verse\"><span class=\"line\">हर औरत में कुछ ऐसा ढूँडते हैं मर्द</span><span class=\"line\">कुछ ऐसा जो हर औरत में नहीं होता</span></div>","<div class=\"verse\"><span class=\"line\">बताऊँ क्या कि वहशत किस को कहते हैं</span><span class=\"line\">बताता गर मैं वहशत में नहीं होता</span></div>","<div class=\"verse\"><span class=\"line\">है डर ताख़ीर का पर जानता भी हूँ</span><span class=\"line\">कि कोई काम 'उजलत में नहीं होता</span></div>","<div class=\"verse\"><span class=\"line\">'अबस आह-ओ-फ़ुग़ाँ करते हो क्यूँ देखो</span><span class=\"line\">नहीं मिलता जो क़िस्मत में नहीं होता</span></div>","<div class=\"verse\"><span class=\"line\">किसी की आबरू पामाल कर के 'ज़ान'</span><span class=\"line\">इज़ाफ़ा अपनी इज़्ज़त में नहीं होता</span></div>"],"versesHtmlEn": ["<div class=\"verse\"><span class=\"line\">Sukoon is darja furqat mein nahin hota</span><span class=\"line\">Agar ye zehan ghaflat mein nahin hota</span></div>","<div class=\"verse\"><span class=\"line\">Wo sab kuchh pa ke bhi aksar rahe be-chain</span><span class=\"line\">Tashakkur jis ki fitrat mein nahin hota</span></div>","<div class=\"verse\"><span class=\"line\">Madad maange koi to be jhijhak karna</span><span class=\"line\">Khasaara is tijaarat mein nahin hota</span></div>","<div class=\"verse\"><span class=\"line\">Magar kya kya nahin hota tasawwur mein</span><span class=\"line\">Agarche kuchh haqeeqat mein nahin hota</span></div>","<div class=\"verse\"><span class=\"line\">Har aurat mein kuchh aisa dhoondte hain mard</span><span class=\"line\">Kuchh aisa jo har aurat mein nahin hota</span></div>","<div class=\"verse\"><span class=\"line\">Bataaun kya ki wahshat kis ko kahte hain</span><span class=\"line\">Bataata gar main wahshat mein nahin hota</span></div>","<div class=\"verse\"><span class=\"line\">Hai dar taakheer ka par jaanta bhi hun</span><span class=\"line\">Ki koi kaam 'ujlat mein nahin hota</span></div>","<div class=\"verse\"><span class=\"line\">'Abas aah-o-fughaan karte ho kyun dekho</span><span class=\"line\">Nahin milta jo qismat mein nahin hota</span></div>","<div class=\"verse\"><span class=\"line\">Kisi ki aabroo paamaal kar ke 'Zaan'</span><span class=\"line\">Izaafa apni izzat mein nahin hota</span></div>"],"firstLineEn": "Sukoon is darja furqat mein nahin hota"},{"id": "ghazal-15","num": 15,"kind": "Ghazal · #15","firstLine": "ख़ुश रहना सीखे इंसान","versesHtml": ["<div class=\"verse\"><span class=\"line\">ख़ुश रहना सीखे इंसान</span><span class=\"line\">ग़म सहना होगा आसान</span></div>","<div class=\"verse\"><span class=\"line\">अपनी हालत ठीक करूँ</span><span class=\"line\">या रक्खूँ अपनों का ध्यान</span></div>","<div class=\"verse\"><span class=\"line\">बहला लेता हूँ ख़ुद को</span><span class=\"line\">ख़ुद का ही कर के गुन-गान</span></div>","<div class=\"verse\"><span class=\"line\">मैं जब आपे में आया</span><span class=\"line\">लोग हुए मुझ से अनजान</span></div>","<div class=\"verse\"><span class=\"line\">दिल के बा-बरकत घर में</span><span class=\"line\">आते जाते हैं मेहमान</span></div>","<div class=\"verse\"><span class=\"line\">सुन मैं तेरा हूँ और बस</span><span class=\"line\">इतनी है मेरी पहचान</span></div>","<div class=\"verse\"><span class=\"line\">मत दुनिया में नुक़्स निकाल</span><span class=\"line\">ख़ुद का ही होगा नुक़सान</span></div>","<div class=\"verse\"><span class=\"line\">हश्र उठाऊँ तो कैसे</span><span class=\"line\">सर पे है बार-ए-एहसान</span></div>","<div class=\"verse\"><span class=\"line\">शहर-ए-ख़िरद में हो कर तुम</span><span class=\"line\">दिल में रखते हो अरमान</span></div>","<div class=\"verse\"><span class=\"line\">चीख़ रही है तन्हाई</span><span class=\"line\">घर है इस दर्जा सुनसान</span></div>","<div class=\"verse\"><span class=\"line\">हैराँ होना छोड़ ही दूँ</span><span class=\"line\">इतना तो मत कर हैरान</span></div>","<div class=\"verse\"><span class=\"line\">घर से दूर है मस्जिद पर</span><span class=\"line\">पास पड़े है क़ब्रिस्तान</span></div>","<div class=\"verse\"><span class=\"line\">कोई तो सुनता था मिरी</span><span class=\"line\">कौन था वो और कब था 'ज़ान'</span></div>"],"versesHtmlEn": ["<div class=\"verse\"><span class=\"line\">Khush rahna seekhe insaan</span><span class=\"line\">Gham sahna hoga aasaan</span></div>","<div class=\"verse\"><span class=\"line\">Apni haalat theek karun</span><span class=\"line\">Ya rakkhun apnon ka dhyaan</span></div>","<div class=\"verse\"><span class=\"line\">Bahla leta hun khud ko</span><span class=\"line\">Khud ka hi kar ke gun-gaan</span></div>","<div class=\"verse\"><span class=\"line\">Main jab aape mein aaya</span><span class=\"line\">Log hue mujh se anjaan</span></div>","<div class=\"verse\"><span class=\"line\">Dil ke ba-barkat ghar mein</span><span class=\"line\">Aate jaate hain mehmaan</span></div>","<div class=\"verse\"><span class=\"line\">Sun main tera hun aur bas</span><span class=\"line\">Itni hai meri pahchaan</span></div>","<div class=\"verse\"><span class=\"line\">Mat duniya mein nuqs nikaal</span><span class=\"line\">Khud ka hi hoga nuqsaan</span></div>","<div class=\"verse\"><span class=\"line\">Hashr uthaaun to kaise</span><span class=\"line\">Sar pe hai baar-e-ehsaan</span></div>","<div class=\"verse\"><span class=\"line\">Shahr-e-khirad mein ho kar tum</span><span class=\"line\">Dil mein rakhte ho armaan</span></div>","<div class=\"verse\"><span class=\"line\">Cheekh rahi hai tanhaai</span><span class=\"line\">Ghar hai is darja sunsaan</span></div>","<div class=\"verse\"><span class=\"line\">Hairaan hona chhod hi dun</span><span class=\"line\">Itna to mat kar hairaan</span></div>","<div class=\"verse\"><span class=\"line\">Ghar se door hai masjid par</span><span class=\"line\">Paas pade hai qabristaan</span></div>","<div class=\"verse\"><span class=\"line\">Koi to sunta tha miri</span><span class=\"line\">Kaun tha wo aur kab tha 'Zaan'</span></div>"],"firstLineEn": "Khush rahna seekhe insaan"},{"id": "ghazal-16","num": 16,"kind": "Ghazal · #16","firstLine": "पहले ख़ुद को क़ाबिल कर","versesHtml": ["<div class=\"verse\"><span class=\"line\">पहले ख़ुद को क़ाबिल कर</span><span class=\"line\">फिर जो चाहे हासिल कर</span></div>","<div class=\"verse\"><span class=\"line\">जिस से मिलना आसाँ हो</span><span class=\"line\">क्या करना उस से मिल कर</span></div>","<div class=\"verse\"><span class=\"line\">आँखों से लेती है काम</span><span class=\"line\">वो अक्सर लब को सिल कर</span></div>","<div class=\"verse\"><span class=\"line\">तू है सहरा का इक फूल</span><span class=\"line\">क्या ही कर लेगा खिल कर</span></div>","<div class=\"verse\"><span class=\"line\">सोचों तक महदूद न रख</span><span class=\"line\">मुझ को दिल में दाख़िल कर</span></div>","<div class=\"verse\"><span class=\"line\">आ ना मेरा हाथ पकड़</span><span class=\"line\">साथ निभाएँगे मिल कर</span></div>","<div class=\"verse\"><span class=\"line\">रो मत मुझको जाने दे</span><span class=\"line\">राह न मेरी मुश्किल कर</span></div>","<div class=\"verse\"><span class=\"line\">भीड़ में शामिल क्यूँ होगा</span><span class=\"line\">भीड़ को ख़ुद में शामिल कर</span></div>","<div class=\"verse\"><span class=\"line\">'ज़ान' पराई दुनिया में</span><span class=\"line\">ख़ुद को ख़ुद पे माइल कर</span></div>"],"versesHtmlEn": ["<div class=\"verse\"><span class=\"line\">Pahle khud ko qaabil kar</span><span class=\"line\">Phir jo chaahe haasil kar</span></div>","<div class=\"verse\"><span class=\"line\">Jis se milna aasaan ho</span><span class=\"line\">Kya karna us se mil kar</span></div>","<div class=\"verse\"><span class=\"line\">Aankhon se leti hai kaam</span><span class=\"line\">Wo aksar lab ko sil kar</span></div>","<div class=\"verse\"><span class=\"line\">Tu hai sahra ka ik phool</span><span class=\"line\">Kya hi kar lega khil kar</span></div>","<div class=\"verse\"><span class=\"line\">Sochon tak mahdood na rakh</span><span class=\"line\">Mujh ko dil mein daakhil kar</span></div>","<div class=\"verse\"><span class=\"line\">Aa na mera haath pakad</span><span class=\"line\">Saath nibhaayenge mil kar</span></div>","<div class=\"verse\"><span class=\"line\">Ro mat mujhko jaane de</span><span class=\"line\">Raah na meri mushkil kar</span></div>","<div class=\"verse\"><span class=\"line\">Bheed mein shaamil kyun hoga</span><span class=\"line\">Bheed ko khud mein shaamil kar</span></div>","<div class=\"verse\"><span class=\"line\">'Zaan' paraai duniya mein</span><span class=\"line\">Khud ko khud pe maail kar</span></div>"],"firstLineEn": "Pahle khud ko qaabil kar"},{"id": "ghazal-17","num": 17,"kind": "Ghazal · #17","firstLine": "अब तो दिल भी पूछ रहा है","versesHtml": ["<div class=\"verse\"><span class=\"line\">अब तो दिल भी पूछ रहा है</span><span class=\"line\">मेरा तुझ से क्या रिश्ता है</span></div>","<div class=\"verse\"><span class=\"line\">तुझ को कैसे दिखलाऊँ मैं</span><span class=\"line\">तुझ में ऐसा क्या देखा है</span></div>","<div class=\"verse\"><span class=\"line\">सब कुछ अपने हक़ में ही हो</span><span class=\"line\">ऐसा भी तो हो सकता है</span></div>","<div class=\"verse\"><span class=\"line\">प्यारे से चेहरे पर तेरे</span><span class=\"line\">गुस्सा भी प्यारा लगता है</span></div>","<div class=\"verse\"><span class=\"line\">दुनिया बैर रखे भी तो क्या</span><span class=\"line\">मुझको तुझ सा यार मिला है</span></div>","<div class=\"verse\"><span class=\"line\">दोस्त भी तू है और ज़ौजा भी</span><span class=\"line\">तुझ पर हर रिश्ता फबता है</span></div>","<div class=\"verse\"><span class=\"line\">औरों से मैं क्यूँ बिछड़ा था</span><span class=\"line\">तुझ से मिलकर 'इल्म हुआ है</span></div>","<div class=\"verse\"><span class=\"line\">'ज़ान' की ग़ज़लें जब पढ़ती है</span><span class=\"line\">'ज़ान' तिरी आँखें पड़ता है</span></div>"],"versesHtmlEn": ["<div class=\"verse\"><span class=\"line\">Ab to dil bhi poochh raha hai</span><span class=\"line\">Mera tujh se kya rishta hai</span></div>","<div class=\"verse\"><span class=\"line\">Tujh ko kaise dikhlaaun main</span><span class=\"line\">Tujh mein aisa kya dekha hai</span></div>","<div class=\"verse\"><span class=\"line\">Sab kuchh apne haq mein hi ho</span><span class=\"line\">Aisa bhi to ho sakta hai</span></div>","<div class=\"verse\"><span class=\"line\">Pyaare se chehre par tere</span><span class=\"line\">Gussa bhi pyaara lagta hai</span></div>","<div class=\"verse\"><span class=\"line\">Duniya bair rakhe bhi to kya</span><span class=\"line\">Mujhko tujh sa yaar mila hai</span></div>","<div class=\"verse\"><span class=\"line\">Dost bhi tu hai aur zauja bhi</span><span class=\"line\">Tujh par har rishta fabta hai</span></div>","<div class=\"verse\"><span class=\"line\">Auron se main kyun bichhda tha</span><span class=\"line\">Tujh se milkar 'ilm hua hai</span></div>","<div class=\"verse\"><span class=\"line\">'Zaan' ki ghazlen jab padhti hai</span><span class=\"line\">'Zaan' tiri aankhen padta hai</span></div>"],"firstLineEn": "Ab to dil bhi poochh raha hai"},{"id": "ghazal-18","num": 18,"kind": "Ghazal · #18","firstLine": "चाहते थे न हो ये फ़साद आप भी","versesHtml": ["<div class=\"verse\"><span class=\"line\">चाहते थे न हो ये फ़साद आप भी</span><span class=\"line\">पर हुआ तो हुए इस पे शाद आप भी</span></div>","<div class=\"verse\"><span class=\"line\">आप तो थे 'अज़ीज़-ए-दिल-ओ-जाँ मिरे</span><span class=\"line\">निकले ना-क़ाबिल-ए-ए'तिमाद आप भी</span></div>","<div class=\"verse\"><span class=\"line\">मुश्किलों में भी लेते थे लुत्फ़ आप तो</span><span class=\"line\">क्या हुआ जो हुए ना-मुराद आप भी</span></div>","<div class=\"verse\"><span class=\"line\">वस्फ़ यकसाँ था सो कैसे निभता ये रब्त</span><span class=\"line\">संग-दिल मैं भी था संग-ज़ाद आप भी</span></div>","<div class=\"verse\"><span class=\"line\">थी मिरी ख़ू कि कहता नहीं था मगर</span><span class=\"line\">मुझ को लगते तो थे कज-निहाद आप भी</span></div>","<div class=\"verse\"><span class=\"line\">पहले तो आप के संग यादें बनीं</span><span class=\"line\">और फिर रह गए बन के याद आप भी</span></div>"],"versesHtmlEn": ["<div class=\"verse\"><span class=\"line\">Chaahte the na ho ye fasaad aap bhi</span><span class=\"line\">Par hua to hue is pe shaad aap bhi</span></div>","<div class=\"verse\"><span class=\"line\">Aap to the 'azeez-e-dil-o-jaan mire</span><span class=\"line\">Nikle na-qaabil-e-e'timaad aap bhi</span></div>","<div class=\"verse\"><span class=\"line\">Mushkilon mein bhi lete the lutf aap to</span><span class=\"line\">Kya hua jo hue na-muraad aap bhi</span></div>","<div class=\"verse\"><span class=\"line\">Wasf yaksaan tha so kaise nibhta ye rabt</span><span class=\"line\">Sang-dil main bhi tha sang-zaad aap bhi</span></div>","<div class=\"verse\"><span class=\"line\">Thi miri khoo ki kahta nahin tha magar</span><span class=\"line\">Mujh ko lagte to the kaj-nihaad aap bhi</span></div>","<div class=\"verse\"><span class=\"line\">Pahle to aap ke sang yaaden banin</span><span class=\"line\">Aur phir rah gae ban ke yaad aap bhi</span></div>"],"firstLineEn": "Chaahte the na ho ye fasaad aap bhi"},{"id": "ghazal-19","num": 19,"kind": "Ghazal · #19","firstLine": "क़ल्ब-ए-ना-शाद की अब ज़रूरत नहीं","versesHtml": ["<div class=\"verse\"><span class=\"line\">क़ल्ब-ए-ना-शाद की अब ज़रूरत नहीं</span><span class=\"line\">सो तिरी याद की अब ज़रूरत नहीं</span></div>","<div class=\"verse\"><span class=\"line\">मुझ को राह-ए-ख़ुदा में ये ख़ल्वत मिली</span><span class=\"line\">मुझ को अफ़राद की अब ज़रूरत नहीं</span></div>","<div class=\"verse\"><span class=\"line\">पड़ चुकी है क़फ़स की अब आदत मुझे</span><span class=\"line\">ज़ुल्म-ए-सय्याद की अब ज़रूरत नहीं</span></div>","<div class=\"verse\"><span class=\"line\">दौलतों के 'इवज़ 'इश्क़ मिलता है याँ</span><span class=\"line\">'इश्क़-ए-फरहाद की अब ज़रूरत नहीं</span></div>","<div class=\"verse\"><span class=\"line\">बुर्द-बारी से सब सीख बैठा हूँ मैं</span><span class=\"line\">दर्स-ए-अजदाद की अब ज़रूरत नहीं</span></div>","<div class=\"verse\"><span class=\"line\">चाहिएँ बस वफ़ादार दो चार दोस्त</span><span class=\"line\">ढेर ता'दाद की अब ज़रूरत नहीं</span></div>","<div class=\"verse\"><span class=\"line\">कल तलक जिस के होने से थी ज़िंदगी</span><span class=\"line\">उस परी-ज़ाद की अब ज़रूरत नहीं</span></div>","<div class=\"verse\"><span class=\"line\">बे-बसी में कभी वो भी तड़पा था 'ज़ान'</span><span class=\"line\">जिस को इमदाद की अब ज़रूरत नहीं</span></div>"],"versesHtmlEn": ["<div class=\"verse\"><span class=\"line\">Qalb-e-na-shaad ki ab zaroorat nahin</span><span class=\"line\">So tiri yaad ki ab zaroorat nahin</span></div>","<div class=\"verse\"><span class=\"line\">Mujh ko raah-e-khuda mein ye khalwat mili</span><span class=\"line\">Mujh ko afraad ki ab zaroorat nahin</span></div>","<div class=\"verse\"><span class=\"line\">Pad chuki hai qafas ki ab aadat mujhe</span><span class=\"line\">Zulm-e-sayyaad ki ab zaroorat nahin</span></div>","<div class=\"verse\"><span class=\"line\">Daulaton ke 'iwaz 'ishq milta hai yaan</span><span class=\"line\">'Ishq-e-farhaad ki ab zaroorat nahin</span></div>","<div class=\"verse\"><span class=\"line\">Burd-baari se sab seekh baitha hun main</span><span class=\"line\">Dars-e-ajdaad ki ab zaroorat nahin</span></div>","<div class=\"verse\"><span class=\"line\">Chaahien bas wafaadaar do chaar dost</span><span class=\"line\">Dher ta'daad ki ab zaroorat nahin</span></div>","<div class=\"verse\"><span class=\"line\">Kal talak jis ke hone se thi zindagi</span><span class=\"line\">Us pari-zaad ki ab zaroorat nahin</span></div>","<div class=\"verse\"><span class=\"line\">Be-basi mein kabhi wo bhi tadpa tha 'Zaan'</span><span class=\"line\">Jis ko imdaad ki ab zaroorat nahin</span></div>"],"firstLineEn": "Qalb-e-na-shaad ki ab zaroorat nahin"},{"id": "ghazal-20","num": 20,"kind": "Ghazal · #20","firstLine": "कोई तो था तेरे जैसा बा'ज़-औक़ात","versesHtml": ["<div class=\"verse\"><span class=\"line\">कोई तो था तेरे जैसा बा'ज़-औक़ात</span><span class=\"line\">ख़ैर वो आलम तो बस था बा'ज़-औक़ात</span></div>","<div class=\"verse\"><span class=\"line\">मुझ से करती है ये तन्हाई हर इक बात</span><span class=\"line\">कुछ यूँ रहता हूँ मैं तन्हा बा'ज़-औक़ात</span></div>","<div class=\"verse\"><span class=\"line\">हाँ मगर क़िस्मत पे किस का ही चले ज़ोर</span><span class=\"line\">हम ने भी चाहा था क्या क्या बा'ज़-औक़ात</span></div>","<div class=\"verse\"><span class=\"line\">है मुयस्सर ज़िंदगी इस शर्त पर अब</span><span class=\"line\">मर के जीना जी के मरना बा'ज़-औक़ात</span></div>","<div class=\"verse\"><span class=\"line\">सोचने से दोस्त आख़िर क्या ही होगा</span><span class=\"line\">मैं ने ऐसा भी है सोचा बा'ज़-औक़ात</span></div>","<div class=\"verse\"><span class=\"line\">उस को माना था तबस्सुम का सबब 'ज़ान'</span><span class=\"line\">पर बड़ा उस ने रुलाया बा'ज़-औक़ात</span></div>"],"versesHtmlEn": ["<div class=\"verse\"><span class=\"line\">Koi to tha tere jaisa baa'z-auqaat</span><span class=\"line\">Khair wo aalam to bas tha baa'z-auqaat</span></div>","<div class=\"verse\"><span class=\"line\">Mujh se karti hai ye tanhaai har ik baat</span><span class=\"line\">Kuchh yun rahta hun main tanha baa'z-auqaat</span></div>","<div class=\"verse\"><span class=\"line\">Haan magar qismat pe kis ka hi chale zor</span><span class=\"line\">Hum ne bhi chaaha tha kya kya baa'z-auqaat</span></div>","<div class=\"verse\"><span class=\"line\">Hai muyassar zindagi is shart par ab</span><span class=\"line\">Mar ke jeena ji ke marna baa'z-auqaat</span></div>","<div class=\"verse\"><span class=\"line\">Sochne se dost aakhir kya hi hoga</span><span class=\"line\">Main ne aisa bhi hai socha baa'z-auqaat</span></div>","<div class=\"verse\"><span class=\"line\">Us ko maana tha tabassum ka sabab 'Zaan'</span><span class=\"line\">Par bada us ne rulaaya baa'z-auqaat</span></div>"],"firstLineEn": "Koi to tha tere jaisa baa'z-auqaat"},{"id": "ghazal-21","num": 21,"kind": "Ghazal · #21","firstLine": "एक ख़ुश-बू चमन छोड़ कर क्या गई","versesHtml": ["<div class=\"verse\"><span class=\"line\">एक ख़ुश-बू चमन छोड़ कर क्या गई</span><span class=\"line\">ग़म में हर इक कली मानो मुरझा गई</span></div>","<div class=\"verse\"><span class=\"line\">हो गए ख़्वाब सब रेज़ा-रेज़ा मिरे</span><span class=\"line\">जब हक़ीक़त तिरी सामने आ गई</span></div>","<div class=\"verse\"><span class=\"line\">इक वो लड़की जो उल्फ़त से लबरेज़ थी</span><span class=\"line\">एक दिन वो भी उल्फ़त से उक्ता गई</span></div>","<div class=\"verse\"><span class=\"line\">कौन थी तू मिरी मैं तिरा कौन था</span><span class=\"line\">क्यूँ मुझे इन सवालों में उलझा गई</span></div>","<div class=\"verse\"><span class=\"line\">फिर बची ही नहीं कोई बात अपने बीच</span><span class=\"line\">बात जब इज़्ज़त-ए-नफ़्स पर आ गई</span></div>","<div class=\"verse\"><span class=\"line\">राएगाँ रह गया सब का हुस्न-ओ-जमाल</span><span class=\"line\">यूँ किसी की मुझे सादगी भा गई</span></div>","<div class=\"verse\"><span class=\"line\">जिन को नज़रों से मैं ने उतारा था 'ज़ान'</span><span class=\"line\">मुझ को शायद उन्हीं की नज़र खा गई</span></div>"],"versesHtmlEn": ["<div class=\"verse\"><span class=\"line\">Ek khush-boo chaman chhod kar kya gai</span><span class=\"line\">Gham mein har ik kali maano murjha gai</span></div>","<div class=\"verse\"><span class=\"line\">Ho gae khwaab sab reza-reza mire</span><span class=\"line\">Jab haqeeqat tiri saamne aa gai</span></div>","<div class=\"verse\"><span class=\"line\">Ik wo ladki jo ulfat se labrez thi</span><span class=\"line\">Ek din wo bhi ulfat se ukta gai</span></div>","<div class=\"verse\"><span class=\"line\">Kaun thi tu miri main tira kaun tha</span><span class=\"line\">Kyun mujhe in sawaalon mein uljha gai</span></div>","<div class=\"verse\"><span class=\"line\">Phir bachi hi nahin koi baat apne beech</span><span class=\"line\">Baat jab izzat-e-nafs par aa gai</span></div>","<div class=\"verse\"><span class=\"line\">Raaegaan rah gaya sab ka husn-o-jamaal</span><span class=\"line\">Yun kisi ki mujhe saadgi bha gai</span></div>","<div class=\"verse\"><span class=\"line\">Jin ko nazron se main ne utaara tha 'Zaan'</span><span class=\"line\">Mujh ko shaayad unhin ki nazar kha gai</span></div>"],"firstLineEn": "Ek khush-boo chaman chhod kar kya gai"},{"id": "ghazal-22","num": 22,"kind": "Ghazal · #22","firstLine": "मैं रहा वहाँ जहाँ","versesHtml": ["<div class=\"verse\"><span class=\"line\">मैं रहा वहाँ जहाँ</span><span class=\"line\">सख़्त था समाँ जहाँ</span></div>","<div class=\"verse\"><span class=\"line\">वो उधर नहीं मिला</span><span class=\"line\">था मुझे गुमाँ जहाँ</span></div>","<div class=\"verse\"><span class=\"line\">ख़ुश-नसीब है ज़मीं</span><span class=\"line\">वा है आसमाँ जहाँ</span></div>","<div class=\"verse\"><span class=\"line\">है तलब कि तू दिखे</span><span class=\"line\">देखूँ मैं जहाँ जहाँ</span></div>","<div class=\"verse\"><span class=\"line\">क्या बशर की आग से</span><span class=\"line\">है धुआँ धुआँ जहाँ</span></div>","<div class=\"verse\"><span class=\"line\">क्या वहाँ कहूँ कि हो</span><span class=\"line\">बे-असर बयाँ जहाँ</span></div>","<div class=\"verse\"><span class=\"line\">कैसी है ये ज़िंदगी</span><span class=\"line\">ग़म हैं राएगाँ जहाँ</span></div>","<div class=\"verse\"><span class=\"line\">साएबाँ हो रब तिरा</span><span class=\"line\">तू हो बे-अमाँ जहाँ</span></div>","<div class=\"verse\"><span class=\"line\">आएगी बहार भी</span><span class=\"line\">आई है ख़िज़ाँ जहाँ</span></div>"],"versesHtmlEn": ["<div class=\"verse\"><span class=\"line\">Main raha wahaan jahaan</span><span class=\"line\">Sakht tha samaan jahaan</span></div>","<div class=\"verse\"><span class=\"line\">Wo udhar nahin mila</span><span class=\"line\">Tha mujhe gumaan jahaan</span></div>","<div class=\"verse\"><span class=\"line\">Khush-naseeb hai zamin</span><span class=\"line\">Wa hai aasmaan jahaan</span></div>","<div class=\"verse\"><span class=\"line\">Hai talab ki tu dikhe</span><span class=\"line\">Dekhun main jahaan jahaan</span></div>","<div class=\"verse\"><span class=\"line\">Kya bashar ki aag se</span><span class=\"line\">Hai dhuaan dhuaan jahaan</span></div>","<div class=\"verse\"><span class=\"line\">Kya wahaan kahun ki ho</span><span class=\"line\">Be-asar bayaan jahaan</span></div>","<div class=\"verse\"><span class=\"line\">Kaisi hai ye zindagi</span><span class=\"line\">Gham hain raaegaan jahaan</span></div>","<div class=\"verse\"><span class=\"line\">Saaebaan ho rab tira</span><span class=\"line\">Tu ho be-amaan jahaan</span></div>","<div class=\"verse\"><span class=\"line\">Aaegi bahaar bhi</span><span class=\"line\">Aai hai khizaan jahaan</span></div>"],"firstLineEn": "Main raha wahaan jahaan"},{"id": "ghazal-23","num": 23,"kind": "Ghazal · #23","firstLine": "जतन कर के भी जब वो शय मिली ही नइं","versesHtml": ["<div class=\"verse\"><span class=\"line\">जतन कर के भी जब वो शय मिली ही नइं</span><span class=\"line\">तो कह डाला कि हाजत हम को थी ही नइं</span></div>","<div class=\"verse\"><span class=\"line\">अगरचे तू समझता है मिरी हर बात</span><span class=\"line\">मगर वो बात जो अब तक कही ही नइं</span></div>","<div class=\"verse\"><span class=\"line\">त'अल्लुक़ वो बला है जो अगर टूटे</span><span class=\"line\">लगे कुछ दिन कि अब तो ज़िंदगी ही नइं</span></div>","<div class=\"verse\"><span class=\"line\">जो कर डाला तिरी आदत को मैं ने तर्क</span><span class=\"line\">किसी की फिर मुझे आदत लगी ही नइं</span></div>","<div class=\"verse\"><span class=\"line\">वफ़ा सीखे कोई मेरी उदासी से</span><span class=\"line\">ये जो आकर कभी वापस गई ही नइं</span></div>","<div class=\"verse\"><span class=\"line\">जो तेरे बा'द अब आई है ख़ल्वत में</span><span class=\"line\">कोई इस से बड़ी आसूदगी ही नइं</span></div>","<div class=\"verse\"><span class=\"line\">जहाँ को छोड़ जब तरजीह दी ख़ुद को</span><span class=\"line\">जहाँ मुझ को लगा फिर लाज़मी ही नइं</span></div>","<div class=\"verse\"><span class=\"line\">रही हैं मुश्किलें काफ़ी सफ़र में पर</span><span class=\"line\">कभी भी ख़्वाहिश-ए-मंज़िल मरी ही नइं</span></div>","<div class=\"verse\"><span class=\"line\">वो क्या दिन थे अज़ीज़ इक आरज़ू थी 'ज़ान'</span><span class=\"line\">पर अब वो आरज़ू बाक़ी रही ही नइं</span></div>"],"versesHtmlEn": ["<div class=\"verse\"><span class=\"line\">Jatan kar ke bhi jab wo shay mili hi nain</span><span class=\"line\">To kah daala ki haajat hum ko thi hi nain</span></div>","<div class=\"verse\"><span class=\"line\">Agarche tu samajhta hai miri har baat</span><span class=\"line\">Magar wo baat jo ab tak kahi hi nain</span></div>","<div class=\"verse\"><span class=\"line\">Ta'alluq wo bala hai jo agar toote</span><span class=\"line\">Lage kuchh din ki ab to zindagi hi nain</span></div>","<div class=\"verse\"><span class=\"line\">Jo kar daala tiri aadat ko main ne tark</span><span class=\"line\">Kisi ki phir mujhe aadat lagi hi nain</span></div>","<div class=\"verse\"><span class=\"line\">Wafa seekhe koi meri udaasi se</span><span class=\"line\">Ye jo aakar kabhi waapas gai hi nain</span></div>","<div class=\"verse\"><span class=\"line\">Jo tere baa'd ab aai hai khalwat mein</span><span class=\"line\">Koi is se badi aasoodagi hi nain</span></div>","<div class=\"verse\"><span class=\"line\">Jahaan ko chhod jab tarjeeh di khud ko</span><span class=\"line\">Jahaan mujh ko laga phir laazmi hi nain</span></div>","<div class=\"verse\"><span class=\"line\">Rahi hain mushkilen kaafi safar mein par</span><span class=\"line\">Kabhi bhi khwaahish-e-manzil mari hi nain</span></div>","<div class=\"verse\"><span class=\"line\">Wo kya din the azeez ik aarzoo thi 'Zaan'</span><span class=\"line\">Par ab wo aarzoo baaqi rahi hi nain</span></div>"],"firstLineEn": "Jatan kar ke bhi jab wo shay mili hi nain"},{"id": "ghazal-24","num": 24,"kind": "Ghazal · #24","firstLine": "समझ बैठा वो आख़िर ना-समझ मुझ को","versesHtml": ["<div class=\"verse\"><span class=\"line\">समझ बैठा वो आख़िर ना-समझ मुझ को</span><span class=\"line\">मैं जिस को ख़ूब कहता था समझ मुझ को</span></div>","<div class=\"verse\"><span class=\"line\">बड़ा आसान था शायद समझना पर</span><span class=\"line\">बड़ी ही देर में आया समझ मुझ को</span></div>","<div class=\"verse\"><span class=\"line\">बढ़ा कर प्यास वो मेरी लगा कहने</span><span class=\"line\">मैं दरिया हूँ मगर सहरा समझ मुझ को</span></div>","<div class=\"verse\"><span class=\"line\">जिसे आँखें कभी समझा नहीं पाईं</span><span class=\"line\">भला उस से मैं क्यूँ कहता समझ मुझ को</span></div>","<div class=\"verse\"><span class=\"line\">न ख़ुद से फ़र्ज़ कर कुछ भी मिरे बारे</span><span class=\"line\">मैं जैसा हूँ कभी वैसा समझ मुझ को</span></div>","<div class=\"verse\"><span class=\"line\">मैं तुझ से भीक क्यूँ माँगूँ मोहब्बत की</span><span class=\"line\">न इतना भी गया गुज़रा समझ मुझ को</span></div>","<div class=\"verse\"><span class=\"line\">अगर रिश्ते में हो जाए फ़ज़ीहत 'आम</span><span class=\"line\">तो उस रिश्ते से वारस्ता समझ मुझ को</span></div>","<div class=\"verse\"><span class=\"line\">ब-जुज़ रब के यहाँ है 'आरज़ी हर साथ</span><span class=\"line\">कम-अज़-कम आ गया इतना समझ मुझ को</span></div>","<div class=\"verse\"><span class=\"line\">ये दिल का टूटना भी लाज़मी था 'ज़ान'</span><span class=\"line\">कभी आती नहीं वरना समझ मुझ को</span></div>"],"versesHtmlEn": ["<div class=\"verse\"><span class=\"line\">Samajh baitha wo aakhir na-samajh mujh ko</span><span class=\"line\">Main jis ko khoob kahta tha samajh mujh ko</span></div>","<div class=\"verse\"><span class=\"line\">Bada aasaan tha shaayad samajhna par</span><span class=\"line\">Badi hi der mein aaya samajh mujh ko</span></div>","<div class=\"verse\"><span class=\"line\">Badha kar pyaas wo meri laga kahne</span><span class=\"line\">Main dariya hun magar sahra samajh mujh ko</span></div>","<div class=\"verse\"><span class=\"line\">Jise aankhen kabhi samjha nahin paain</span><span class=\"line\">Bhala us se main kyun kahta samajh mujh ko</span></div>","<div class=\"verse\"><span class=\"line\">Na khud se farz kar kuchh bhi mire baare</span><span class=\"line\">Main jaisa hun kabhi waisa samajh mujh ko</span></div>","<div class=\"verse\"><span class=\"line\">Main tujh se bheek kyun maangun mohabbat ki</span><span class=\"line\">Na itna bhi gaya guzra samajh mujh ko</span></div>","<div class=\"verse\"><span class=\"line\">Agar rishte mein ho jaae fazeehat 'aam</span><span class=\"line\">To us rishte se waarasta samajh mujh ko</span></div>","<div class=\"verse\"><span class=\"line\">Ba-juz rab ke yahaan hai 'aarzi har saath</span><span class=\"line\">Kam-az-kam aa gaya itna samajh mujh ko</span></div>","<div class=\"verse\"><span class=\"line\">Ye dil ka tootna bhi laazmi tha 'Zaan'</span><span class=\"line\">Kabhi aati nahin warna samajh mujh ko</span></div>"],"firstLineEn": "Samajh baitha wo aakhir na-samajh mujh ko"},{"id": "ghazal-25","num": 25,"kind": "Ghazal · #25","firstLine": "मैं तो अक्सर तन्हाई में बैठे ये सोचूँ","versesHtml": ["<div class=\"verse\"><span class=\"line\">मैं तो अक्सर तन्हाई में बैठे ये सोचूँ</span><span class=\"line\">अपनों के होते भी क्या मैं इतना तन्हा हूँ</span></div>","<div class=\"verse\"><span class=\"line\">माना दुख का नाता मुझ से पैहम है लेकिन</span><span class=\"line\">कम-अज़-कम ख़ुश रहने की ख़ुश-फ़हमी ही पालूँ</span></div>","<div class=\"verse\"><span class=\"line\">कुछ करने से पहले गर सोचूँ तो क्या ही हो</span><span class=\"line\">बेहतर है जो करना है बिन सोचे कर गुज़रूँ</span></div>","<div class=\"verse\"><span class=\"line\">बार अब ज़िम्मेदारी का ढोना है मुझ को भी</span><span class=\"line\">मुमकिन है अब मैं भी अपने ख़्वाबों को बेचूँ</span></div>","<div class=\"verse\"><span class=\"line\">इश्क़-ओ-नफ़रत दोनों ही रस्सी के हैं मानिंद</span><span class=\"line\">उतना ही आगे जाएँ पीछे जितना खींचूँ</span></div>","<div class=\"verse\"><span class=\"line\">सोचा था दुनिया को खो कर ख़ुद को पा लूँगा</span><span class=\"line\">अब ख़ुद को भी खो बैठा हूँ अब मैं क्या पाऊँ</span></div>","<div class=\"verse\"><span class=\"line\">तन मन की इक आज़ारी है ये फ़िक्र-ए-फ़र्दा</span><span class=\"line\">वो आज़ारी जिस के दम से ही मैं ऐसा हूँ</span></div>","<div class=\"verse\"><span class=\"line\">गो ख़ुद को रोके रखता हूँ मुस्तक़बिल को सोच</span><span class=\"line\">पर उड़ने का मन करता है जब अम्बर देखूँ</span></div>","<div class=\"verse\"><span class=\"line\">सब वाक़िफ़ हैं हर रस्ते की इक ही मंज़िल है</span><span class=\"line\">फिर भी रस्ता चुनने में सब इतना सोचें क्यूँ</span></div>","<div class=\"verse\"><span class=\"line\">जो मुझ को दरिया समझें बुझती है उन की प्यास</span><span class=\"line\">जो सहरा समझें मैं उन को प्यासा ही रक्खूँ</span></div>","<div class=\"verse\"><span class=\"line\">बाहर से कामिल जाने है जग सारा मुझ को</span><span class=\"line\">\"ज़ान\" अंदर की वीरानी को बस मैं ही जानूँ</span></div>"],"versesHtmlEn": ["<div class=\"verse\"><span class=\"line\">Main to aksar tanhaai mein baithe ye sochun</span><span class=\"line\">Apnon ke hote bhi kya main itna tanha hun</span></div>","<div class=\"verse\"><span class=\"line\">Maana dukh ka naata mujh se paiham hai lekin</span><span class=\"line\">Kam-az-kam khush rahne ki khush-fahmi hi paalun</span></div>","<div class=\"verse\"><span class=\"line\">Kuchh karne se pahle gar sochun to kya hi ho</span><span class=\"line\">Behatar hai jo karna hai bin soche kar guzrun</span></div>","<div class=\"verse\"><span class=\"line\">Baar ab zimmedaari ka dhona hai mujh ko bhi</span><span class=\"line\">Mumkin hai ab main bhi apne khwaabon ko bechun</span></div>","<div class=\"verse\"><span class=\"line\">Ishq-o-nafrat donon hi rassi ke hain maanind</span><span class=\"line\">Utna hi aage jaaen peechhe jitna khinchun</span></div>","<div class=\"verse\"><span class=\"line\">Socha tha duniya ko kho kar khud ko pa lunga</span><span class=\"line\">Ab khud ko bhi kho baitha hun ab main kya paaun</span></div>","<div class=\"verse\"><span class=\"line\">Tan man ki ik aazaari hai ye fikr-e-farda</span><span class=\"line\">Wo aazaari jis ke dam se hi main aisa hun</span></div>","<div class=\"verse\"><span class=\"line\">Go khud ko roke rakhta hun mustaqbil ko soch</span><span class=\"line\">Par udne ka man karta hai jab ambar dekhun</span></div>","<div class=\"verse\"><span class=\"line\">Sab waaqif hain har raste ki ik hi manzil hai</span><span class=\"line\">Phir bhi rasta chunne mein sab itna sochen kyun</span></div>","<div class=\"verse\"><span class=\"line\">Jo mujh ko dariya samjhen bujhti hai un ki pyaas</span><span class=\"line\">Jo sahra samjhen main un ko pyaasa hi rakkhun</span></div>","<div class=\"verse\"><span class=\"line\">Baahar se kaamil jaane hai jag saara mujh ko</span><span class=\"line\">'Zaan' andar ki weeraani ko bas main hi jaanun</span></div>"],"firstLineEn": "Main to aksar tanhaai mein baithe ye sochun"},{"id": "ghazal-26","num": 26,"kind": "Ghazal · #26","firstLine": "मौसम तो फिर मौसम है","versesHtml": ["<div class=\"verse\"><span class=\"line\">मौसम तो फिर मौसम है</span><span class=\"line\">बदला भी तो क्या ग़म है</span></div>","<div class=\"verse\"><span class=\"line\">तू बस वाजेह है मुझ को</span><span class=\"line\">बाक़ी दुनिया मुबहम है</span></div>","<div class=\"verse\"><span class=\"line\">ज़ुल्मत मुझ को यूँ चूमे</span><span class=\"line\">गोया मेरी बेगम है</span></div>","<div class=\"verse\"><span class=\"line\">ग़म की मुझ से निस्बत है</span><span class=\"line\">और ये निस्बत पैहम है</span></div>","<div class=\"verse\"><span class=\"line\">मुझ मुरझाए से गुल को</span><span class=\"line\">तेरा हँसना शबनम है</span></div>","<div class=\"verse\"><span class=\"line\">जीवन जिस को कहते हैं</span><span class=\"line\">मरने तक का मातम है</span></div>","<div class=\"verse\"><span class=\"line\">क्या फिर तर्क-ए-जज़्बा ही</span><span class=\"line\">दर्द-ए-दिल का मरहम है</span></div>","<div class=\"verse\"><span class=\"line\">सब उस का ग़ुस्सा देखें</span><span class=\"line\">गो आँख उस की पुर-नम है</span></div>","<div class=\"verse\"><span class=\"line\">कल अश्कों से धोई थी</span><span class=\"line\">सूरत अब ताज़ा-दम है</span></div>","<div class=\"verse\"><span class=\"line\">इतने ख़ुश क्यूँ दिखते हो</span><span class=\"line\">तुम को आख़िर क्या ग़म है</span></div>","<div class=\"verse\"><span class=\"line\">शहर-ए-दिल में मुद्दत से</span><span class=\"line\">बाद-ए-फ़रहाँ मद्धम है</span></div>","<div class=\"verse\"><span class=\"line\">इंसाँ के ख़ातिर इंसाँ</span><span class=\"line\">कुछ भी कर गुज़रे कम है</span></div>"],"versesHtmlEn": ["<div class=\"verse\"><span class=\"line\">Mausam to phir mausam hai</span><span class=\"line\">Badla bhi to kya gham hai</span></div>","<div class=\"verse\"><span class=\"line\">Tu bas waazeh hai mujh ko</span><span class=\"line\">Baaqi duniya mubham hai</span></div>","<div class=\"verse\"><span class=\"line\">Zulmat mujh ko yun choome</span><span class=\"line\">Goya meri begam hai</span></div>","<div class=\"verse\"><span class=\"line\">Gham ki mujh se nisbat hai</span><span class=\"line\">Aur ye nisbat paiham hai</span></div>","<div class=\"verse\"><span class=\"line\">Mujh murjhaae se gul ko</span><span class=\"line\">Tera hansna shabnam hai</span></div>","<div class=\"verse\"><span class=\"line\">Jeevan jis ko kahte hain</span><span class=\"line\">Marne tak ka maatam hai</span></div>","<div class=\"verse\"><span class=\"line\">Kya phir tark-e-jazba hi</span><span class=\"line\">Dard-e-dil ka marham hai</span></div>","<div class=\"verse\"><span class=\"line\">Sab us ka gussa dekhen</span><span class=\"line\">Go aankh us ki pur-nam hai</span></div>","<div class=\"verse\"><span class=\"line\">Kal ashkon se dhoi thi</span><span class=\"line\">Soorat ab taaza-dam hai</span></div>","<div class=\"verse\"><span class=\"line\">Itne khush kyun dikhte ho</span><span class=\"line\">Tum ko aakhir kya gham hai</span></div>","<div class=\"verse\"><span class=\"line\">Shahr-e-dil mein muddat se</span><span class=\"line\">Baad-e-farhaan maddham hai</span></div>","<div class=\"verse\"><span class=\"line\">Insaan ke khaatir insaan</span><span class=\"line\">Kuchh bhi kar guzre kam hai</span></div>"],"firstLineEn": "Mausam to phir mausam hai"},{"id": "ghazal-27","num": 27,"kind": "Ghazal · #27","firstLine": "अगर मुझ को तेरा सहारा न हो","versesHtml": ["<div class=\"verse\"><span class=\"line\">अगर मुझ को तेरा सहारा न हो</span><span class=\"line\">मिरा इस जहाँ में गुज़ारा न हो</span></div>","<div class=\"verse\"><span class=\"line\">वो हर बार ये कह के बख़्शे ख़ता</span><span class=\"line\">'मगर याद रखना दुबारा न हो'</span></div>","<div class=\"verse\"><span class=\"line\">न रख इश्क़ में फ़ाइदे की उमीद</span><span class=\"line\">अगर चाहता है ख़सारा न हो</span></div>","<div class=\"verse\"><span class=\"line\">मुक़द्दर भी उस को हराता नहीं</span><span class=\"line\">जिसे हार जाना गवारा नहो</span></div>","<div class=\"verse\"><span class=\"line\">कोई ऐसा फ़ातेह मुझे भी दिखा</span><span class=\"line\">कभी ज़िंदगी में जो हारा न हो</span></div>","<div class=\"verse\"><span class=\"line\">तवज्जोह तिरी चाहता हूँ मैं पर</span><span class=\"line\">तिरा ध्यान मुझ पे ही सारा न हो</span></div>","<div class=\"verse\"><span class=\"line\">बशर में हों चाहे हुनर लाख ही</span><span class=\"line\">पर एहसाँ जताने का यारा न हो</span></div>","<div class=\"verse\"><span class=\"line\">ये इंसाँ मिलेंगे तिरे दर पे ही</span><span class=\"line\">ब-जुज़ तेरे गर कोई चारा न हो</span></div>","<div class=\"verse\"><span class=\"line\">भँवर देखता है सफ़ीने को यूँ</span><span class=\"line\">समुंदर का गोया किनारा न हो</span></div>","<div class=\"verse\"><span class=\"line\">ख़ुदा-रा न तुम को मिले ऐसा शख़्स</span><span class=\"line\">तुम्हारा जो हो कर तुम्हारा न हो</span></div>","<div class=\"verse\"><span class=\"line\">मोहब्बत हो गर तो मोहब्बत हो बस</span><span class=\"line\">मोहब्बत का फिर गोशवारा न हो</span></div>","<div class=\"verse\"><span class=\"line\">इन आँखों से फिर पूछना मेरा हाल</span><span class=\"line\">जो हुलिये से गर आशकारा न हो</span></div>","<div class=\"verse\"><span class=\"line\">कहीं फिर दवा ज़हर लगने लगे</span><span class=\"line\">कोई ज़ख़्म इतना भी प्यारा न हो</span></div>"],"versesHtmlEn": ["<div class=\"verse\"><span class=\"line\">Agar mujh ko tera sahaara na ho</span><span class=\"line\">Mira is jahaan mein guzaara na ho</span></div>","<div class=\"verse\"><span class=\"line\">Wo har baar ye kah ke bakhshe khata</span><span class=\"line\">'Magar yaad rakhna dubaara na ho'</span></div>","<div class=\"verse\"><span class=\"line\">Na rakh ishq mein faaide ki umeed</span><span class=\"line\">Agar chaahta hai khasaara na ho</span></div>","<div class=\"verse\"><span class=\"line\">Muqaddar bhi us ko haraata nahin</span><span class=\"line\">Jise haar jaana gawaara na ho</span></div>","<div class=\"verse\"><span class=\"line\">Koi aisa faateh mujhe bhi dikha</span><span class=\"line\">Kabhi zindagi mein jo haara na ho</span></div>","<div class=\"verse\"><span class=\"line\">Tawajjoh tiri chaahta hun main par</span><span class=\"line\">Tira dhyaan mujh pe hi saara na ho</span></div>","<div class=\"verse\"><span class=\"line\">Bashar mein hon chaahe hunar laakh hi</span><span class=\"line\">Par ehsaan jataane ka yaara na ho</span></div>","<div class=\"verse\"><span class=\"line\">Ye insaan milenge tire dar pe hi</span><span class=\"line\">Ba-juz tere gar koi chaara na ho</span></div>","<div class=\"verse\"><span class=\"line\">Bhanwar dekhta hai safeene ko yun</span><span class=\"line\">Samundar ka goya kinaara na ho</span></div>","<div class=\"verse\"><span class=\"line\">Khuda-ra na tum ko mile aisa shakhs</span><span class=\"line\">Tumhaara jo ho kar tumhaara na ho</span></div>","<div class=\"verse\"><span class=\"line\">Mohabbat ho gar to mohabbat ho bas</span><span class=\"line\">Mohabbat ka phir goshwaara na ho</span></div>","<div class=\"verse\"><span class=\"line\">In aankhon se phir poochhna mera haal</span><span class=\"line\">Jo huliye se gar aashkaara na ho</span></div>","<div class=\"verse\"><span class=\"line\">Kahin phir dawa zahar lagne lage</span><span class=\"line\">Koi zakhm itna bhi pyaara na ho</span></div>"],"firstLineEn": "Agar mujh ko tera sahaara na ho"},{"id": "ghazal-28","num": 28,"kind": "Ghazal · #28","firstLine": "न इस क़दर तू देख ख़ुद को इश्तिबाह से","versesHtml": ["<div class=\"verse\"><span class=\"line\">न इस क़दर तू देख ख़ुद को इश्तिबाह से</span><span class=\"line\">कोई नहीं यहाँ जो बच सका गुनाह से</span></div>","<div class=\"verse\"><span class=\"line\">हर एक क़िस्म के हैं ग़म मिरे भी पास पर</span><span class=\"line\">गुरेज़ कर रहा हूँ मैं मेरी ही आह से</span></div>","<div class=\"verse\"><span class=\"line\">मैं तेरा कुछ नहीं ये तेरे लब कहें मगर</span><span class=\"line\">कभी 'अयाँ हुआ नहीं तिरी निगाह से</span></div>","<div class=\"verse\"><span class=\"line\">मिरी ख़िरद ख़राब कर रही है शायरी</span><span class=\"line\">मुझे ख़बर हुई है मेरे ख़ैर-ख़्वाह से</span></div>","<div class=\"verse\"><span class=\"line\">इक आरज़ू हो गर तो हों हज़ार काविशें</span><span class=\"line\">किसे मिला है कुछ यहाँ पे सिर्फ़ चाह से</span></div>","<div class=\"verse\"><span class=\"line\">ये बे-कली मिरे बदन को छोड़ती नहीं</span><span class=\"line\">कनीज़ कब ख़फ़ा हुई है बादशाह से</span></div>","<div class=\"verse\"><span class=\"line\">ज़वाल उस बशर को रब ने लाज़मी दिया</span><span class=\"line\">कभी सँभल सका नहीं जो इंतिबाह से</span></div>","<div class=\"verse\"><span class=\"line\">हुआ है कुछ तो तेरे साथ इश्क़ में जो तू</span><span class=\"line\">पनाह माँगता है इश्क़-ए-बे-पनाह से</span></div>","<div class=\"verse\"><span class=\"line\">वफ़ा की अहमियत फिर उस को क्या पता हो 'ज़ान'</span><span class=\"line\">सदा जो भागता रहा हो रस्म-ओ-राह से</span></div>"],"versesHtmlEn": ["<div class=\"verse\"><span class=\"line\">Na is qadar tu dekh khud ko ishtibaah se</span><span class=\"line\">Koi nahin yahaan jo bach saka gunaah se</span></div>","<div class=\"verse\"><span class=\"line\">Har ek qism ke hain gham mire bhi paas par</span><span class=\"line\">Gurez kar raha hun main meri hi aah se</span></div>","<div class=\"verse\"><span class=\"line\">Main tera kuchh nahin ye tere lab kahen magar</span><span class=\"line\">Kabhi 'ayaan hua nahin tiri nigaah se</span></div>","<div class=\"verse\"><span class=\"line\">Miri khirad kharaab kar rahi hai shaayari</span><span class=\"line\">Mujhe khabar hui hai mere khair-khwaah se</span></div>","<div class=\"verse\"><span class=\"line\">Ik aarzoo ho gar to hon hazaar kaavishen</span><span class=\"line\">Kise mila hai kuchh yahaan pe sirf chaah se</span></div>","<div class=\"verse\"><span class=\"line\">Ye be-kali mire badan ko chhodti nahin</span><span class=\"line\">Kaneez kab khafa hui hai baadshaah se</span></div>","<div class=\"verse\"><span class=\"line\">Zawaal us bashar ko rab ne laazmi diya</span><span class=\"line\">Kabhi sanbhal saka nahin jo intibaah se</span></div>","<div class=\"verse\"><span class=\"line\">Hua hai kuchh to tere saath ishq mein jo tu</span><span class=\"line\">Panaah maangta hai ishq-e-be-panaah se</span></div>","<div class=\"verse\"><span class=\"line\">Wafa ki ahamiyat phir us ko kya pata ho 'Zaan'</span><span class=\"line\">Sada jo bhaagta raha ho rasm-o-raah se</span></div>"],"firstLineEn": "Na is qadar tu dekh khud ko ishtibaah se"},{"id": "ghazal-29","num": 29,"kind": "Ghazal · #29","firstLine": "त'अल्लुक़ जब उस रब से अच्छा हुआ","versesHtml": ["<div class=\"verse\"><span class=\"line\">त'अल्लुक़ जब उस रब से अच्छा हुआ</span><span class=\"line\">मैं इक ख़ाक से जैसे सोना हुआ</span></div>","<div class=\"verse\"><span class=\"line\">मैं जब भी हुआ गुम-शुदा दहर में</span><span class=\"line\">तिरे पास आया भटकता हुआ</span></div>","<div class=\"verse\"><span class=\"line\">मिरे पास क्या है ये पूछे जहाँ</span><span class=\"line\">मिरे पास तू है तो क्या क्या हुआ</span></div>","<div class=\"verse\"><span class=\"line\">मुझे तो नहीं ख़ुद पे भी इख़्तियार</span><span class=\"line\">हुआ तेरे दम से मैं जैसा हुआ</span></div>","<div class=\"verse\"><span class=\"line\">गिनी जब भी मैं ने तिरी नेमतें</span><span class=\"line\">मिरा दीन-ओ-ईमाँ भी ताज़ा हुआ</span></div>","<div class=\"verse\"><span class=\"line\">मैं तकलीफ़ में जब पुकारूँ तुझे</span><span class=\"line\">दिखे मुझ को आराम आता हुआ</span></div>","<div class=\"verse\"><span class=\"line\">गुनहगार हूँ तेरा माना मगर</span><span class=\"line\">मैं मोमिन हूँ आख़िर ये अच्छा हुआ</span></div>","<div class=\"verse\"><span class=\"line\">गिराता भी है तो फ़क़त इस लिए</span><span class=\"line\">कि देखे तू मुझ को ख़ुद उठता हुआ</span></div>","<div class=\"verse\"><span class=\"line\">दिखाता है तू उस को ऊँचा मक़ाम</span><span class=\"line\">दिखे जो भी सजदों में झुकता हुआ</span></div>","<div class=\"verse\"><span class=\"line\">हक़ीक़त है तू मुझ को ईमान है</span><span class=\"line\">ये दुनिया तो झूठा फ़साना हुआ</span></div>","<div class=\"verse\"><span class=\"line\">मैं रखता हूँ बस तुझ पे ही एतिमाद</span><span class=\"line\">जहाँ में बशर कब बशर का हुआ</span></div>","<div class=\"verse\"><span class=\"line\">मुझे शुक्रिया रब का करना था 'ज़ान'</span><span class=\"line\">ग़ज़ल तो फ़क़त इक बहाना हुआ</span></div>"],"versesHtmlEn": ["<div class=\"verse\"><span class=\"line\">Ta'alluq jab us rab se achchha hua</span><span class=\"line\">Main ik khaak se jaise sona hua</span></div>","<div class=\"verse\"><span class=\"line\">Main jab bhi hua gum-shuda dahr mein</span><span class=\"line\">Tire paas aaya bhatakta hua</span></div>","<div class=\"verse\"><span class=\"line\">Mire paas kya hai ye poochhe jahaan</span><span class=\"line\">Mire paas tu hai to kya kya hua</span></div>","<div class=\"verse\"><span class=\"line\">Mujhe to nahin khud pe bhi ikhtiyaar</span><span class=\"line\">Hua tere dam se main jaisa hua</span></div>","<div class=\"verse\"><span class=\"line\">Gini jab bhi main ne tiri ne'maten</span><span class=\"line\">Mira deen-o-eemaan bhi taaza hua</span></div>","<div class=\"verse\"><span class=\"line\">Main takleef mein jab pukaarun tujhe</span><span class=\"line\">Dikhe mujh ko aaraam aata hua</span></div>","<div class=\"verse\"><span class=\"line\">Gunahgaar hun tera maana magar</span><span class=\"line\">Main momin hun aakhir ye achchha hua</span></div>","<div class=\"verse\"><span class=\"line\">Giraata bhi hai to faqat is liye</span><span class=\"line\">Ki dekhe tu mujh ko khud uthta hua</span></div>","<div class=\"verse\"><span class=\"line\">Dikhaata hai tu us ko ooncha maqaam</span><span class=\"line\">Dikhe jo bhi sajdon mein jhukta hua</span></div>","<div class=\"verse\"><span class=\"line\">Haqeeqat hai tu mujh ko eemaan hai</span><span class=\"line\">Ye duniya to jhootha fasaana hua</span></div>","<div class=\"verse\"><span class=\"line\">Main rakhta hun bas tujh pe hi etimaad</span><span class=\"line\">Jahaan mein bashar kab bashar ka hua</span></div>","<div class=\"verse\"><span class=\"line\">Mujhe shukriya rab ka karna tha 'Zaan'</span><span class=\"line\">Ghazal to faqat ik bahaana hua</span></div>"],"firstLineEn": "Ta'alluq jab us rab se achchha hua"},{"id": "ghazal-30","num": 30,"kind": "Ghazal · #30","firstLine": "तवील रास्ता है हाथ थाम लीजिए","versesHtml": ["<div class=\"verse\"><span class=\"line\">तवील रास्ता है हाथ थाम लीजिए</span><span class=\"line\">कि दिल के साथ 'अक़्ल से भी काम लीजिए</span></div>","<div class=\"verse\"><span class=\"line\">बहार में ख़ुदा को याद कीजिए भी क्यूँ</span><span class=\"line\">ख़िज़ाँ में पर उसी का ख़ूब नाम लीजिए</span></div>","<div class=\"verse\"><span class=\"line\">अगर दवा-ए-दर्द-ए-दिल है मुझ से गुफ़्तुगू</span><span class=\"line\">तो आप इस दवा को सुब्ह-ओ-शाम लीजिए</span></div>","<div class=\"verse\"><span class=\"line\">सनम से चाह मेरी कुछ न थी ब-जुज़ वफ़ा</span><span class=\"line\">शबाब पर कहे कि लुत्फ़-ए-'आम लीजिए</span></div>","<div class=\"verse\"><span class=\"line\">सफ़र में ज़ीस्त के मिले न कुछ गँवाए बिन</span><span class=\"line\">यहाँ तो जोखिमों को बहर-गाम लीजिए</span></div>","<div class=\"verse\"><span class=\"line\">मुनाफ़िक़ों का फ़ैसला ख़ुदा पे छोड़िये</span><span class=\"line\">मु'आफ़ कीजिए न इंतिक़ाम लीजिए</span></div>","<div class=\"verse\"><span class=\"line\">त'आम भी हिदायतों का फिर न हो नसीब</span><span class=\"line\">न इस क़दर भी लज़्ज़त-ए-हराम लीजिए</span></div>","<div class=\"verse\"><span class=\"line\">है जुम्बिश-ए-ज़बान का ये ज़ब्त जब तलक</span><span class=\"line\">कि तब तलक तो नैन का पयाम लीजिए</span></div>","<div class=\"verse\"><span class=\"line\">भले मुहिब हो लाख पर उसूल ये है 'ज़ान'</span><span class=\"line\">किसी का अपने सर न इत्तिहाम लीजिए</span></div>"],"versesHtmlEn": ["<div class=\"verse\"><span class=\"line\">Taweel raasta hai haath thaam lijiye</span><span class=\"line\">Ki dil ke saath 'aql se bhi kaam lijiye</span></div>","<div class=\"verse\"><span class=\"line\">Bahaar mein khuda ko yaad kijiye bhi kyun</span><span class=\"line\">Khizaan mein par usi ka khoob naam lijiye</span></div>","<div class=\"verse\"><span class=\"line\">Agar dawa-e-dard-e-dil hai mujh se guftugu</span><span class=\"line\">To aap is dawa ko subh-o-shaam lijiye</span></div>","<div class=\"verse\"><span class=\"line\">Sanam se chaah meri kuchh na thi ba-juz wafa</span><span class=\"line\">Shabaab par kahe ki lutf-e-'aam lijiye</span></div>","<div class=\"verse\"><span class=\"line\">Safar mein zeest ke mile na kuchh ganvaae bin</span><span class=\"line\">Yahaan to jokhimon ko bahr-gaam lijiye</span></div>","<div class=\"verse\"><span class=\"line\">Munaafiqon ka faisla khuda pe chhodiye</span><span class=\"line\">Mu'aaf kijiye na intiqaam lijiye</span></div>","<div class=\"verse\"><span class=\"line\">Ta'aam bhi hidaayaton ka phir na ho naseeb</span><span class=\"line\">Na is qadar bhi lazzat-e-haraam lijiye</span></div>","<div class=\"verse\"><span class=\"line\">Hai jumbish-e-zabaan ka ye zabt jab talak</span><span class=\"line\">Ki tab talak to nain ka payaam lijiye</span></div>","<div class=\"verse\"><span class=\"line\">Bhale muhib ho laakh par usool ye hai 'Zaan'</span><span class=\"line\">Kisi ka apne sar na ittihaam lijiye</span></div>"],"firstLineEn": "Taweel raasta hai haath thaam lijiye"},{"id": "ghazal-31","num": 31,"kind": "Ghazal · #31","firstLine": "बहुत मुमकिन है अब इस बार उदासी देर तक जाए","versesHtml": ["<div class=\"verse\"><span class=\"line\">बहुत मुमकिन है अब इस बार उदासी देर तक जाए</span><span class=\"line\">मगर इस बार डर भी है कि मेरी जाँ न थक जाए</span></div>","<div class=\"verse\"><span class=\"line\">ज़मीं वाले ज़मीं वालों के चक्कर में पड़ा है क्यूँ</span><span class=\"line\">कहीं तेरे न हाथों से निकल तेरा फ़लक जाए</span></div>","<div class=\"verse\"><span class=\"line\">नज़र इतना न आओ तुम कि फिर तुम को ही देखें सब</span><span class=\"line\">न जाने कौन कब किस की निगाहों में खटक जाए</span></div>","<div class=\"verse\"><span class=\"line\">बहुत सीधा है यूँ तो रास्ता रब तक पहुँचने का</span><span class=\"line\">मगर वो है तवील इतना कि मुझ जैसा भटक जाए</span></div>","<div class=\"verse\"><span class=\"line\">अंधेरे से घिरे इस दिल को बस तेरी ही हाजत है</span><span class=\"line\">तेरी ताबिंदगी-ए-हुस्न से हर शय चमक जाए</span></div>","<div class=\"verse\"><span class=\"line\">मिरी क़िस्मत की है नाराज़गी भी इस क़दर मुझ से</span><span class=\"line\">मैं जितना पास आ जाऊँ ये उतनी ही खिसक जाए</span></div>","<div class=\"verse\"><span class=\"line\">मैं क्यूँ थक हार कर बैठूँ कि बेहतर है वहाँ चल दूँ</span><span class=\"line\">जहाँ लेकर मुझे मेरी उमीदों की सड़क जाए</span></div>","<div class=\"verse\"><span class=\"line\">तुम आ जाओ मिलो मुझ से मगर इतना सुनो देखो</span><span class=\"line\">बहुत मुमकिन है आग इस जिस्म की यक-दम भड़क जाए</span></div>","<div class=\"verse\"><span class=\"line\">हसीं हो कर भी उस ने सिर्फ़ मुझ से ही मोहब्बत की</span><span class=\"line\">भला उस की वफाओं पर मिरा कैसे न शक जाए</span></div>","<div class=\"verse\"><span class=\"line\">वो इक बच्चा जो अक्सर ही बड़ा होने से कतराए</span><span class=\"line\">कहो उस से सलीब-ए-वक़्त पर आ कर लटक जाए</span></div>","<div class=\"verse\"><span class=\"line\">तू इतनी ख़ूब-सूरत है कि तुझ को रिंद अगर देखे</span><span class=\"line\">तो फिर बस इस क़दर देखे कि जाम उस का छलक जाए</span></div>","<div class=\"verse\"><span class=\"line\">मैं दूजों के ग़मों में ख़ूब रो लूँ पर ग़नीमत है</span><span class=\"line\">कभी ख़ुद के लिए मेरा इक आँसू भी टपक जाए</span></div>","<div class=\"verse\"><span class=\"line\">अगर करनी मुझे आती तो मैं कब का न कर लेता</span><span class=\"line\">शुरू कर गुफ़्तुगू तू ही कि मेरी ये झिझक जाए</span></div>","<div class=\"verse\"><span class=\"line\">ज़रूरत तो मुझे होगी दलीलों की गवाहों की</span><span class=\"line\">तिरी पोशाक-ए-गिर्या तो तिरे हर ऐब ढक जाए</span></div>","<div class=\"verse\"><span class=\"line\">वो सब से आश्ना भी है तो इस में क्या नया है \"ज़ान\"</span><span class=\"line\">वो है बरसात की ख़ुशबू जो हर इक सू महक जाए</span></div>"],"versesHtmlEn": ["<div class=\"verse\"><span class=\"line\">Bahut mumkin hai ab is baar udaasi der tak jaae</span><span class=\"line\">Magar is baar dar bhi hai ki meri jaan na thak jaae</span></div>","<div class=\"verse\"><span class=\"line\">Zamin waale zamin waalon ke chakkar mein pada hai kyun</span><span class=\"line\">Kahin tere na haathon se nikal tera falak jaae</span></div>","<div class=\"verse\"><span class=\"line\">Nazar itna na aao tum ki phir tum ko hi dekhen sab</span><span class=\"line\">Na jaane kaun kab kis ki nigaahon mein khatak jaae</span></div>","<div class=\"verse\"><span class=\"line\">Bahut seedha hai yun to raasta rab tak pahunchne ka</span><span class=\"line\">Magar wo hai taweel itna ki mujh jaisa bhatak jaae</span></div>","<div class=\"verse\"><span class=\"line\">Andhere se ghire is dil ko bas teri hi haajat hai</span><span class=\"line\">Teri taabindagi-e-husn se har shay chamak jaae</span></div>","<div class=\"verse\"><span class=\"line\">Miri qismat ki hai naaraazgi bhi is qadar mujh se</span><span class=\"line\">Main jitna paas aa jaaun ye utni hi khisak jaae</span></div>","<div class=\"verse\"><span class=\"line\">Main kyun thak haar kar baithun ki behatar hai wahaan chal dun</span><span class=\"line\">Jahaan lekar mujhe meri umeedon ki sadak jaae</span></div>","<div class=\"verse\"><span class=\"line\">Tum aa jaao milo mujh se magar itna suno dekho</span><span class=\"line\">Bahut mumkin hai aag is jism ki yak-dam bhadak jaae</span></div>","<div class=\"verse\"><span class=\"line\">Hasin ho kar bhi us ne sirf mujh se hi mohabbat ki</span><span class=\"line\">Bhala us ki wafaaon par mira kaise na shak jaae</span></div>","<div class=\"verse\"><span class=\"line\">Wo ik bachcha jo aksar hi bada hone se katraae</span><span class=\"line\">Kaho us se saleeb-e-waqt par aa kar latak jaae</span></div>","<div class=\"verse\"><span class=\"line\">Tu itni khoob-soorat hai ki tujh ko rind agar dekhe</span><span class=\"line\">To phir bas is qadar dekhe ki jaam us ka chhalak jaae</span></div>","<div class=\"verse\"><span class=\"line\">Main doojon ke ghamon mein khoob ro lun par ghaneemat hai</span><span class=\"line\">Kabhi khud ke liye mera ik aansoo bhi tapak jaae</span></div>","<div class=\"verse\"><span class=\"line\">Agar karni mujhe aati to main kab ka na kar leta</span><span class=\"line\">Shuru kar guftugu tu hi ki meri ye jhijhak jaae</span></div>","<div class=\"verse\"><span class=\"line\">Zaroorat to mujhe hogi daleelon ki gawaahon ki</span><span class=\"line\">Tiri poshaak-e-girya to tire har aib dhak jaae</span></div>","<div class=\"verse\"><span class=\"line\">Wo sab se aashna bhi hai to is mein kya naya hai 'Zaan'</span><span class=\"line\">Wo hai barsaat ki khushboo jo har ik soo mahak jaae</span></div>"],"firstLineEn": "Bahut mumkin hai ab is baar udaasi der tak jaae"},{"id": "ghazal-32","num": 32,"kind": "Ghazal · #32","firstLine": "ज़िन्दगी भी कैसी चाल चल रही है","versesHtml": ["<div class=\"verse\"><span class=\"line\">ज़िन्दगी भी कैसी चाल चल रही है</span><span class=\"line\">ख़ुद को ही गिरा के ख़ुद सँभल रही है</span></div>","<div class=\"verse\"><span class=\"line\">जाँ निकल न जाए ख़ौफ़ आ रहा है</span><span class=\"line\">आज इस तरह ये शाम ढल रही है</span></div>","<div class=\"verse\"><span class=\"line\">वास्ता हमारा बर्फ़ की तरह था</span><span class=\"line\">बर्फ़ ठोस थी पर अब पिघल रही है</span></div>","<div class=\"verse\"><span class=\"line\">छोड़ दी थी मैं ने वो ख़राब आदत</span><span class=\"line\">आज पर तबी'अत फिर मचल रही है</span></div>","<div class=\"verse\"><span class=\"line\">क्या बहार ये है ये ख़िज़ाँ के जैसी</span><span class=\"line\">तुम ने तो कहा था रुत बदल रही है</span></div>","<div class=\"verse\"><span class=\"line\">क्यूँ इधर उधर की बात कर रहा है</span><span class=\"line\">कोई तो तुझे भी बात खल रही है</span></div>","<div class=\"verse\"><span class=\"line\">ज़ेहन के क़फ़स से जब से हूँ मैं निकला</span><span class=\"line\">यार हर मुसीबत ख़ुद ही टल रही है</span></div>","<div class=\"verse\"><span class=\"line\">आज कल भला क्यूँ बे सबब ही ख़ुश हूँ</span><span class=\"line\">देख ये उदासी हाथ मल रही है</span></div>","<div class=\"verse\"><span class=\"line\">चाहतों की बारिश कब तलक ही होती</span><span class=\"line\">धूप नफ़रतों की फिर निकल रही है</span></div>","<div class=\"verse\"><span class=\"line\">मेरी हर ख़ुशी ही रेत के है मानिंद</span><span class=\"line\">रेत हाथ में है और फ़िसल रही है</span></div>","<div class=\"verse\"><span class=\"line\">क्यूँ ये फ़िक्र-ए-फ़र्दा इस क़दर है भूकी</span><span class=\"line\">आज की भी ख़ुशियाँ क्यूँ निगल रही है</span></div>","<div class=\"verse\"><span class=\"line\">तीरगी बहुत है यूँ तो मेरे दिल में</span><span class=\"line\">पर उमीद की इक शम'अ जल रही है</span></div>","<div class=\"verse\"><span class=\"line\">'ज़ान' बिन डरे ही आतिश-ए-जिगर पे</span><span class=\"line\">उस की याद नंगे पाँव चल रही है</span></div>"],"versesHtmlEn": ["<div class=\"verse\"><span class=\"line\">Zindagi bhi kaisi chaal chal rahi hai</span><span class=\"line\">Khud ko hi gira ke khud sanbhal rahi hai</span></div>","<div class=\"verse\"><span class=\"line\">Jaan nikal na jaae khauf aa raha hai</span><span class=\"line\">Aaj is tarah ye shaam dhal rahi hai</span></div>","<div class=\"verse\"><span class=\"line\">Waasta hamaara barf ki tarah tha</span><span class=\"line\">Barf thos thi par ab pighal rahi hai</span></div>","<div class=\"verse\"><span class=\"line\">Chhod di thi main ne wo kharaab aadat</span><span class=\"line\">Aaj par tabi'at phir machal rahi hai</span></div>","<div class=\"verse\"><span class=\"line\">Kya bahaar ye hai ye khizaan ke jaisi</span><span class=\"line\">Tum ne to kaha tha rut badal rahi hai</span></div>","<div class=\"verse\"><span class=\"line\">Kyun idhar udhar ki baat kar raha hai</span><span class=\"line\">Koi to tujhe bhi baat khal rahi hai</span></div>","<div class=\"verse\"><span class=\"line\">Zehan ke qafas se jab se hun main nikla</span><span class=\"line\">Yaar har museebat khud hi tal rahi hai</span></div>","<div class=\"verse\"><span class=\"line\">Aaj kal bhala kyun be sabab hi khush hun</span><span class=\"line\">Dekh ye udaasi haath mal rahi hai</span></div>","<div class=\"verse\"><span class=\"line\">Chaahaton ki baarish kab talak hi hoti</span><span class=\"line\">Dhoop nafraton ki phir nikal rahi hai</span></div>","<div class=\"verse\"><span class=\"line\">Meri har khushi hi ret ke hai maanind</span><span class=\"line\">Ret haath mein hai aur fisal rahi hai</span></div>","<div class=\"verse\"><span class=\"line\">Kyun ye fikr-e-farda is qadar hai bhooki</span><span class=\"line\">Aaj ki bhi khushiyaan kyun nigal rahi hai</span></div>","<div class=\"verse\"><span class=\"line\">Teergi bahut hai yun to mere dil mein</span><span class=\"line\">Par umeed ki ik sham'a jal rahi hai</span></div>","<div class=\"verse\"><span class=\"line\">'Zaan' bin dare hi aatish-e-jigar pe</span><span class=\"line\">Us ki yaad nange paanv chal rahi hai</span></div>"],"firstLineEn": "Zindagi bhi kaisi chaal chal rahi hai"},{"id": "ghazal-33","num": 33,"kind": "Ghazal · #33","firstLine": "मलाल था मिली शिकस्त तेरी चाल से","versesHtml": ["<div class=\"verse\"><span class=\"line\">मलाल था मिली शिकस्त तेरी चाल से</span><span class=\"line\">मगर खुला ये ज़ेहन फिर इसी मलाल से</span></div>","<div class=\"verse\"><span class=\"line\">निकल गया है कब का मेरे दिल से तू मगर</span><span class=\"line\">नहीं निकल रहा है क्यूँ मिरे ख़याल से</span></div>","<div class=\"verse\"><span class=\"line\">मिजाज़ से मिरे तू मेरा हाल भाँप मत</span><span class=\"line\">मिरा मिजाज़ मुख़्तलिफ़ है मेरे हाल से</span></div>","<div class=\"verse\"><span class=\"line\">मैं शम्स हूँ कि जिस का है उरूज लाज़मी</span><span class=\"line\">न रख तू ख़ुद को शाद यूँ मिरे ज़वाल से</span></div>","<div class=\"verse\"><span class=\"line\">था मुद्दतों से ख़ुश्क मेरी ग़फ़लतों से जो</span><span class=\"line\">वो फूल खिल उठा है आज देख भाल से</span></div>","<div class=\"verse\"><span class=\"line\">था ख़ुद की ही क़बील से असद डरा हुआ</span><span class=\"line\">वो फस चुका था इश्क़ कर के इक ग़ज़ाल से</span></div>","<div class=\"verse\"><span class=\"line\">हर एक अश्क पोछने को लाख शाने हैं</span><span class=\"line\">तुझे है फ़ाइदा बहुत तिरे जमाल से</span></div>","<div class=\"verse\"><span class=\"line\">वो बारहा वही सवाल पूछता रहा</span><span class=\"line\">था बारहा गुरेज़ मुझ को जिस सवाल से</span></div>","<div class=\"verse\"><span class=\"line\">वो रुख़्सती के वक़्त मुझ को यूँ लगा था ख़ुश</span><span class=\"line\">की गोया कुछ ख़ुशी न थी उसे विसाल से</span></div>","<div class=\"verse\"><span class=\"line\">वो मिल गया तो उस की अहमियत नहीं रही</span><span class=\"line\">मैं जिस का मुंतज़िर रहा था इतने साल से</span></div>","<div class=\"verse\"><span class=\"line\">वो इक नज़र से हल करे सभी के मस'अले</span><span class=\"line\">गिला नहीं किसी को हुस्न-ए-बे-मिसाल से</span></div>"],"versesHtmlEn": ["<div class=\"verse\"><span class=\"line\">Malaal tha mili shikast teri chaal se</span><span class=\"line\">Magar khula ye zehan phir isi malaal se</span></div>","<div class=\"verse\"><span class=\"line\">Nikal gaya hai kab ka mere dil se tu magar</span><span class=\"line\">Nahin nikal raha hai kyun mire khayaal se</span></div>","<div class=\"verse\"><span class=\"line\">Mizaaj se mire tu mera haal bhaanp mat</span><span class=\"line\">Mira mizaaj mukhtalif hai mere haal se</span></div>","<div class=\"verse\"><span class=\"line\">Main shams hun ki jis ka hai urooj laazmi</span><span class=\"line\">Na rakh tu khud ko shaad yun mire zawaal se</span></div>","<div class=\"verse\"><span class=\"line\">Tha muddaton se khushk meri ghaflaton se jo</span><span class=\"line\">Wo phool khil utha hai aaj dekh bhaal se</span></div>","<div class=\"verse\"><span class=\"line\">Tha khud ki hi qabeel se asad dara hua</span><span class=\"line\">Wo phas chuka tha ishq kar ke ik ghazaal se</span></div>","<div class=\"verse\"><span class=\"line\">Har ek ashk pochhne ko laakh shaane hain</span><span class=\"line\">Tujhe hai faaida bahut tire jamaal se</span></div>","<div class=\"verse\"><span class=\"line\">Wo baar-ha wahi sawaal poochhta raha</span><span class=\"line\">Tha baar-ha gurez mujh ko jis sawaal se</span></div>","<div class=\"verse\"><span class=\"line\">Wo rukhsati ke waqt mujh ko yun laga tha khush</span><span class=\"line\">Ki goya kuchh khushi na thi use wisaal se</span></div>","<div class=\"verse\"><span class=\"line\">Wo mil gaya to us ki ahamiyat nahin rahi</span><span class=\"line\">Main jis ka muntazir raha tha itne saal se</span></div>","<div class=\"verse\"><span class=\"line\">Wo ik nazar se hal kare sabhi ke mas'ale</span><span class=\"line\">Gila nahin kisi ko husn-e-be-misaal se</span></div>"],"firstLineEn": "Malaal tha mili shikast teri chaal se"},{"id": "ghazal-34","num": 34,"kind": "Ghazal · #34","firstLine": "जब से वो मेरे अपने गैरों में बट गए","versesHtml": ["<div class=\"verse\"><span class=\"line\">जब से वो मेरे अपने गैरों में बट गए</span><span class=\"line\">उम्मीद के तो जैसे बादल ही छट गए</span></div>","<div class=\"verse\"><span class=\"line\">ग़म यूँ तो बाँटने से अब तक बढ़े ही थे</span><span class=\"line\">पर संग तेरे बाँटे तो ये भी घट गए</span></div>","<div class=\"verse\"><span class=\"line\">मुश्किल था काम वैसे यूँ भूलना उसे</span><span class=\"line\">इस काम से मगर हम कब के निपट गए</span></div>","<div class=\"verse\"><span class=\"line\">इमदाद में तिरी तो हाजिर बहुत थे ना</span><span class=\"line\">तो क्या हुआ अगर हम पीछे भी हट गए</span></div>","<div class=\"verse\"><span class=\"line\">कितने अजीब थे वो अपने त'अल्लुक़ात</span><span class=\"line\">ख़ुद फैलते गए फिर ख़ुद ही सिमट गए</span></div>","<div class=\"verse\"><span class=\"line\">आए तो थे बहुत से यूँ रास्ते में साथ</span><span class=\"line\">मंज़िल थी दूर तो फिर सब ही पलट गए</span></div>","<div class=\"verse\"><span class=\"line\">यूँ उस ने मुस्कुरा कर जब अलविदा कहा</span><span class=\"line\">उस से बग़ैर सोचे हम तो लिपट गए</span></div>","<div class=\"verse\"><span class=\"line\">दिन रात माँगते थे जिस को ख़ुदा से हम</span><span class=\"line\">उस के बग़ैर ही फिर दिन रात कट गए</span></div>","<div class=\"verse\"><span class=\"line\">थे मुद्दतों से भूके वो जानवर सभी</span><span class=\"line\">सो ज़हर भी परोसा तो सब झपट गए</span></div>","<div class=\"verse\"><span class=\"line\">रख कर यक़ीं ख़ुदा पर कुछ यूँ हुआ कि हम</span><span class=\"line\">पीछे नहीं हटे जो इक बार डट गए</span></div>"],"versesHtmlEn": ["<div class=\"verse\"><span class=\"line\">Jab se wo mere apne gairon mein bat gae</span><span class=\"line\">Ummeed ke to jaise baadal hi chhat gae</span></div>","<div class=\"verse\"><span class=\"line\">Gham yun to baantne se ab tak badhe hi the</span><span class=\"line\">Par sang tere baante to ye bhi ghat gae</span></div>","<div class=\"verse\"><span class=\"line\">Mushkil tha kaam waise yun bhoolna use</span><span class=\"line\">Is kaam se magar hum kab ke nipat gae</span></div>","<div class=\"verse\"><span class=\"line\">Imdaad mein tiri to haazir bahut the na</span><span class=\"line\">To kya hua agar hum peechhe bhi hat gae</span></div>","<div class=\"verse\"><span class=\"line\">Kitne ajeeb the wo apne ta'alluqaat</span><span class=\"line\">Khud phailte gae phir khud hi simat gae</span></div>","<div class=\"verse\"><span class=\"line\">Aae to the bahut se yun raaste mein saath</span><span class=\"line\">Manzil thi door to phir sab hi palat gae</span></div>","<div class=\"verse\"><span class=\"line\">Yun us ne muskura kar jab alvida kaha</span><span class=\"line\">Us se bagair soche hum to lipat gae</span></div>","<div class=\"verse\"><span class=\"line\">Din raat maangte the jis ko khuda se hum</span><span class=\"line\">Us ke bagair hi phir din raat kat gae</span></div>","<div class=\"verse\"><span class=\"line\">The muddaton se bhooke wo jaanwar sabhi</span><span class=\"line\">So zahar bhi parosa to sab jhapat gae</span></div>","<div class=\"verse\"><span class=\"line\">Rakh kar yaqeen khuda par kuchh yun hua ki hum</span><span class=\"line\">Peechhe nahin hate jo ik baar dat gae</span></div>"],"firstLineEn": "Jab se wo mere apne gairon mein bat gae"},{"id": "ghazal-35","num": 35,"kind": "Ghazal · #35","firstLine": "देख ख़ुद को छुप रहा था आइना","versesHtml": ["<div class=\"verse\"><span class=\"line\">देख ख़ुद को छुप रहा था आइना</span><span class=\"line\">आइने को जब दिखाया आइना</span></div>","<div class=\"verse\"><span class=\"line\">देख सकता जिस में मैं किरदार भी</span><span class=\"line\">काश होता कोई ऐसा आइना</span></div>","<div class=\"verse\"><span class=\"line\">कोई भी इस में मुकम्मल कब दिखे</span><span class=\"line\">ज़िंदगी है एक छोटा आइना</span></div>","<div class=\"verse\"><span class=\"line\">क्या दिखेगी साफ़ अब सूरत मिरी</span><span class=\"line\">ले लिया है साफ़-सुथरा आइना</span></div>","<div class=\"verse\"><span class=\"line\">राज़ दूजों के न खोलो क्या पता</span><span class=\"line\">हश्र में हो कौन किस का आइना</span></div>","<div class=\"verse\"><span class=\"line\">भेस बदला जब किसी नक़्क़ाल ने</span><span class=\"line\">देख उस को ख़ूब रोया आइना</span></div>","<div class=\"verse\"><span class=\"line\">'अक्स तो पर सब में इक जैसा दिखे</span><span class=\"line\">क्या नया फिर क्या पुराना आइना</span></div>","<div class=\"verse\"><span class=\"line\">गो है ज़ंग-आलूद पर कहता है सच</span><span class=\"line\">तजरबों वाला वो बूढ़ा आइना</span></div>","<div class=\"verse\"><span class=\"line\">क्यूँ नहीं तब बोल पाया झूट वो</span><span class=\"line\">सामने जब उस के रक्खा आइना</span></div>"],"versesHtmlEn": ["<div class=\"verse\"><span class=\"line\">Dekh khud ko chhup raha tha aaina</span><span class=\"line\">Aaine ko jab dikhaaya aaina</span></div>","<div class=\"verse\"><span class=\"line\">Dekh sakta jis mein main kirdaar bhi</span><span class=\"line\">Kaash hota koi aisa aaina</span></div>","<div class=\"verse\"><span class=\"line\">Koi bhi is mein mukammal kab dikhe</span><span class=\"line\">Zindagi hai ek chhota aaina</span></div>","<div class=\"verse\"><span class=\"line\">Kya dikhegi saaf ab soorat miri</span><span class=\"line\">Le liya hai saaf-suthra aaina</span></div>","<div class=\"verse\"><span class=\"line\">Raaz doojon ke na kholo kya pata</span><span class=\"line\">Hashr mein ho kaun kis ka aaina</span></div>","<div class=\"verse\"><span class=\"line\">Bhes badla jab kisi naqqaal ne</span><span class=\"line\">Dekh us ko khoob roya aaina</span></div>","<div class=\"verse\"><span class=\"line\">'Aks to par sab mein ik jaisa dikhe</span><span class=\"line\">Kya naya phir kya puraana aaina</span></div>","<div class=\"verse\"><span class=\"line\">Go hai zang-aalood par kahta hai sach</span><span class=\"line\">Tajrabon waala wo boodha aaina</span></div>","<div class=\"verse\"><span class=\"line\">Kyun nahin tab bol paaya jhoot wo</span><span class=\"line\">Saamne jab us ke rakkha aaina</span></div>"],"firstLineEn": "Dekh khud ko chhup raha tha aaina"},{"id": "ghazal-36","num": 36,"kind": "Ghazal · #36","firstLine": "ऐ दरिया तू शामिल कर ले अपने लोगों में","versesHtml": ["<div class=\"verse\"><span class=\"line\">ऐ दरिया तू शामिल कर ले अपने लोगों में</span><span class=\"line\">वर्ना मैं भी रह जाऊँगा प्यासे लोगों में</span></div>","<div class=\"verse\"><span class=\"line\">दिल की ऐनक से ये देखें सारी दुनिया को</span><span class=\"line\">शायद ये ख़ामी होती है अच्छे लोगों में</span></div>","<div class=\"verse\"><span class=\"line\">फट से अच्छे बनते हैं ये मतलब की ख़ातिर</span><span class=\"line\">शायद ये ख़ूबी होती है गंदे लोगों में</span></div>","<div class=\"verse\"><span class=\"line\">दौलत कामिल है पर कपड़े छोटे हैं तन पर</span><span class=\"line\">कितनी सस्ती ग़ैरत है इन महँगे लोगों में</span></div>","<div class=\"verse\"><span class=\"line\">काम आओ मत इन के फिर देखो क्या होता है</span><span class=\"line\">कड़वा-पन घुल जाएगा इन मीठे लोगों में</span></div>","<div class=\"verse\"><span class=\"line\">इन के लहजे से लगती हैं बातें सच इन की</span><span class=\"line\">ये फ़ितरत होती है अक्सर झूटे लोगों में</span></div>","<div class=\"verse\"><span class=\"line\">हर मज़हब के त्यौहारों में घुल मिल जाते थे</span><span class=\"line\">कितनी अच्छी आदत थी ये तब के लोगों में</span></div>","<div class=\"verse\"><span class=\"line\">माना इस दुनिया में चेहरे हैं अरबों-खरबों</span><span class=\"line\">पर देखो ना तुम भाए हो इतने लोगों में</span></div>","<div class=\"verse\"><span class=\"line\">मेरी ग़ीबत कर के चाहें मुझ से ही शफ़क़त</span><span class=\"line\">कैसे आए इतनी हिम्मत ऐसे लोगों में</span></div>"],"versesHtmlEn": ["<div class=\"verse\"><span class=\"line\">Ai dariya tu shaamil kar le apne logon mein</span><span class=\"line\">Warna main bhi rah jaaunga pyaase logon mein</span></div>","<div class=\"verse\"><span class=\"line\">Dil ki ainak se ye dekhen saari duniya ko</span><span class=\"line\">Shaayad ye khaami hoti hai achchhe logon mein</span></div>","<div class=\"verse\"><span class=\"line\">Phat se achchhe bante hain ye matlab ki khaatir</span><span class=\"line\">Shaayad ye khoobi hoti hai gande logon mein</span></div>","<div class=\"verse\"><span class=\"line\">Daulat kaamil hai par kapde chhote hain tan par</span><span class=\"line\">Kitni sasti ghairat hai in mahnge logon mein</span></div>","<div class=\"verse\"><span class=\"line\">Kaam aao mat in ke phir dekho kya hota hai</span><span class=\"line\">Kadwa-pan ghul jaaega in meethe logon mein</span></div>","<div class=\"verse\"><span class=\"line\">In ke lahje se lagti hain baaten sach in ki</span><span class=\"line\">Ye fitrat hoti hai aksar jhoote logon mein</span></div>","<div class=\"verse\"><span class=\"line\">Har mazhab ke tyauhaaron mein ghul mil jaate the</span><span class=\"line\">Kitni achchhi aadat thi ye tab ke logon mein</span></div>","<div class=\"verse\"><span class=\"line\">Maana is duniya mein chehre hain arbon-kharbon</span><span class=\"line\">Par dekho na tum bhaae ho itne logon mein</span></div>","<div class=\"verse\"><span class=\"line\">Meri ghibat kar ke chaahen mujh se hi shafqat</span><span class=\"line\">Kaise aae itni himmat aise logon mein</span></div>"],"firstLineEn": "Ai dariya tu shaamil kar le apne logon mein"},{"id": "ghazal-37","num": 37,"kind": "Ghazal · #37","firstLine": "देखने को क्या है मेरे सामने","versesHtml": ["<div class=\"verse\"><span class=\"line\">देखने को क्या है मेरे सामने</span><span class=\"line\">आइना रक्खा है मेरे सामने</span></div>","<div class=\"verse\"><span class=\"line\">बा'द उस के और तो क्या होना था</span><span class=\"line\">इक नई दुनिया है मेरे सामने</span></div>","<div class=\"verse\"><span class=\"line\">कुछ नज़र आता नहीं तेरे सिवा</span><span class=\"line\">जब भी तू आता है मेरे सामने</span></div>","<div class=\"verse\"><span class=\"line\">पीठ पीछे क्या हुआ होगा वो भी</span><span class=\"line\">जो नहीं होता है मेरे सामने</span></div>","<div class=\"verse\"><span class=\"line\">कश्ती तू मुझ को बचा तो लेगी ना</span><span class=\"line\">इक तलातुम सा है मेरे सामने</span></div>","<div class=\"verse\"><span class=\"line\">मैं मुख़ातब सिर्फ़ इस से ही रहा</span><span class=\"line\">मेरा जो साया है मेरे सामने</span></div>","<div class=\"verse\"><span class=\"line\">सोचा था बातें करेंगे और तू</span><span class=\"line\">रूठ के बैठा है मेरे सामने</span></div>","<div class=\"verse\"><span class=\"line\">फ़ोन पर क्या कुछ नहीं कहता मगर</span><span class=\"line\">चुप खड़ा रहता है मेरे सामने</span></div>","<div class=\"verse\"><span class=\"line\">फ़ख़्र से मेरा ख़ुदा कह सकता है</span><span class=\"line\">\"ज़ान\" बस झुकता है मेरे सामने</span></div>"],"versesHtmlEn": ["<div class=\"verse\"><span class=\"line\">Dekhne ko kya hai mere saamne</span><span class=\"line\">Aaina rakkha hai mere saamne</span></div>","<div class=\"verse\"><span class=\"line\">Baa'd us ke aur to kya hona tha</span><span class=\"line\">Ik nai duniya hai mere saamne</span></div>","<div class=\"verse\"><span class=\"line\">Kuchh nazar aata nahin tere siwa</span><span class=\"line\">Jab bhi tu aata hai mere saamne</span></div>","<div class=\"verse\"><span class=\"line\">Peeth peechhe kya hua hoga wo bhi</span><span class=\"line\">Jo nahin hota hai mere saamne</span></div>","<div class=\"verse\"><span class=\"line\">Kashti tu mujh ko bacha to legi na</span><span class=\"line\">Ik talaatum sa hai mere saamne</span></div>","<div class=\"verse\"><span class=\"line\">Main mukhaatab sirf is se hi raha</span><span class=\"line\">Mera jo saaya hai mere saamne</span></div>","<div class=\"verse\"><span class=\"line\">Socha tha baaten karenge aur tu</span><span class=\"line\">Rooth ke baitha hai mere saamne</span></div>","<div class=\"verse\"><span class=\"line\">Phone par kya kuchh nahin kahta magar</span><span class=\"line\">Chup khada rahta hai mere saamne</span></div>","<div class=\"verse\"><span class=\"line\">Fakhr se mera khuda kah sakta hai</span><span class=\"line\">'Zaan' bas jhukta hai mere saamne</span></div>"],"firstLineEn": "Dekhne ko kya hai mere saamne"},{"id": "ghazal-38","num": 38,"kind": "Ghazal · #38","firstLine": "जाने वो कितनी आगे हो","versesHtml": ["<div class=\"verse\"><span class=\"line\">जाने वो कितनी आगे हो</span><span class=\"line\">जिस मंज़िल के तुम पीछे हो</span></div>","<div class=\"verse\"><span class=\"line\">तुम से कैसे बोले कोई</span><span class=\"line\">क्यूँ उखड़े उखड़े रहते हो</span></div>","<div class=\"verse\"><span class=\"line\">कर बैठे ना उसको रुसवा</span><span class=\"line\">जो मुँह में आए बकते हो</span></div>","<div class=\"verse\"><span class=\"line\">बाहर से इतना हँसते हो</span><span class=\"line\">अंदर से कितना रोते हो</span></div>","<div class=\"verse\"><span class=\"line\">पूरा तन है लर्ज़ां देखो</span><span class=\"line\">क्यूँ मेरे नज़दीक आते हो</span></div>","<div class=\"verse\"><span class=\"line\">लड़ते हैं अपनों की ख़ातिर</span><span class=\"line\">तुम तो अपनों से लड़ते हो</span></div>","<div class=\"verse\"><span class=\"line\">हर इक हिस्सा इस दुनिया का</span><span class=\"line\">मन ही मन में घूम आते हो</span></div>","<div class=\"verse\"><span class=\"line\">साथ अपने रक्खो तुम मुझ को</span><span class=\"line\">तुम बिलकुल मेरे जैसे हो</span></div>","<div class=\"verse\"><span class=\"line\">तुम को सब हसरत से ताकें</span><span class=\"line\">तो क्या तुम इतने महँगे हो</span></div>","<div class=\"verse\"><span class=\"line\">महबूबा की या सपनों की</span><span class=\"line\">तुम किस की ख़ातिर जागे हो</span></div>","<div class=\"verse\"><span class=\"line\">ख़ुशबू ख़ुशबू क्यूँ है हर-सू</span><span class=\"line\">शायद तुम घर से निकले हो</span></div>","<div class=\"verse\"><span class=\"line\">रब से तुम को माँगा है तो</span><span class=\"line\">कह सकता हूँ तुम मेरे हो</span></div>"],"versesHtmlEn": ["<div class=\"verse\"><span class=\"line\">Jaane wo kitni aage ho</span><span class=\"line\">Jis manzil ke tum peechhe ho</span></div>","<div class=\"verse\"><span class=\"line\">Tum se kaise bole koi</span><span class=\"line\">Kyun ukhde ukhde rahte ho</span></div>","<div class=\"verse\"><span class=\"line\">Kar baithe na usko ruswa</span><span class=\"line\">Jo munh mein aae bakte ho</span></div>","<div class=\"verse\"><span class=\"line\">Baahar se itna hanste ho</span><span class=\"line\">Andar se kitna rote ho</span></div>","<div class=\"verse\"><span class=\"line\">Poora tan hai larzaan dekho</span><span class=\"line\">Kyun mere nazdeek aate ho</span></div>","<div class=\"verse\"><span class=\"line\">Ladte hain apnon ki khaatir</span><span class=\"line\">Tum to apnon se ladte ho</span></div>","<div class=\"verse\"><span class=\"line\">Har ik hissa is duniya ka</span><span class=\"line\">Man hi man mein ghoom aate ho</span></div>","<div class=\"verse\"><span class=\"line\">Saath apne rakkho tum mujh ko</span><span class=\"line\">Tum bilkul mere jaise ho</span></div>","<div class=\"verse\"><span class=\"line\">Tum ko sab hasrat se taaken</span><span class=\"line\">To kya tum itne mahnge ho</span></div>","<div class=\"verse\"><span class=\"line\">Mahbooba ki ya sapnon ki</span><span class=\"line\">Tum kis ki khaatir jaage ho</span></div>","<div class=\"verse\"><span class=\"line\">Khushboo khushboo kyun hai har-soo</span><span class=\"line\">Shaayad tum ghar se nikle ho</span></div>","<div class=\"verse\"><span class=\"line\">Rab se tum ko maanga hai to</span><span class=\"line\">Kah sakta hun tum mere ho</span></div>"],"firstLineEn": "Jaane wo kitni aage ho"},{"id": "ghazal-39","num": 39,"kind": "Ghazal · #39","firstLine": "हमीं हैं रिफ़ाक़त में जाँ देते हैं","versesHtml": ["<div class=\"verse\"><span class=\"line\">हमीं हैं रिफ़ाक़त में जाँ देते हैं</span><span class=\"line\">वगरना सभी बस गुमाँ देते हैं</span></div>","<div class=\"verse\"><span class=\"line\">कभी बात हम बस पते की करें</span><span class=\"line\">कभी उल्टे सीधे बयाँ देते हैं</span></div>","<div class=\"verse\"><span class=\"line\">कभी छोटे लोगों में बैठा नहीं</span><span class=\"line\">बड़े ख़्वाब इजाज़त कहाँ देते हैं</span></div>","<div class=\"verse\"><span class=\"line\">परे आसमाँ के है कोई जिसे</span><span class=\"line\">यूँ आवाज़ दोनों जहाँ देते हैं</span></div>","<div class=\"verse\"><span class=\"line\">कमी बाग़बानी में थी सो चलो</span><span class=\"line\">चमन को नया बागबाँ देते हैं</span></div>","<div class=\"verse\"><span class=\"line\">हिदायत मिले जाने कब ही तुम्हें</span><span class=\"line\">मुअज़्ज़िन तो अब भी अज़ाँ देते हैं</span></div>","<div class=\"verse\"><span class=\"line\">किराए पे रहते थे ख़ुद जो कभी</span><span class=\"line\">किराए पे अब वो मकाँ देते हैं</span></div>","<div class=\"verse\"><span class=\"line\">मुकरते नहीं हम किसी हाल पर</span><span class=\"line\">अगर हम किसी को ज़बाँ देते हैं</span></div>","<div class=\"verse\"><span class=\"line\">ख़ुदा जानता है कि साबिर हैं हम</span><span class=\"line\">सो हाँ रोज़-ओ-शब इम्तिहाँ देते हैं</span></div>","<div class=\"verse\"><span class=\"line\">तेरी चश्म-ए-गिर्या के धोके सदा</span><span class=\"line\">बहुत सो को दर्द-ए-निहाँ देते हैं</span></div>","<div class=\"verse\"><span class=\"line\">भले मौसमों में भी कैसा सुकूँ</span><span class=\"line\">सभी कुछ वो कर राएगाँ देते हैं</span></div>","<div class=\"verse\"><span class=\"line\">करूँ ख़ूबियों का अगर ज़िक्र मैं</span><span class=\"line\">गिना वो मेरी ख़ामियाँ देते हैं</span></div>"],"versesHtmlEn": ["<div class=\"verse\"><span class=\"line\">Hamin hain rifaaqat mein jaan dete hain</span><span class=\"line\">Wagarna sabhi bas gumaan dete hain</span></div>","<div class=\"verse\"><span class=\"line\">Kabhi baat hum bas pate ki karen</span><span class=\"line\">Kabhi ulte seedhe bayaan dete hain</span></div>","<div class=\"verse\"><span class=\"line\">Kabhi chhote logon mein baitha nahin</span><span class=\"line\">Bade khwaab ijaazat kahaan dete hain</span></div>","<div class=\"verse\"><span class=\"line\">Pare aasmaan ke hai koi jise</span><span class=\"line\">Yun aawaaz donon jahaan dete hain</span></div>","<div class=\"verse\"><span class=\"line\">Kami baaghbaani mein thi so chalo</span><span class=\"line\">Chaman ko naya baagbaan dete hain</span></div>","<div class=\"verse\"><span class=\"line\">Hidaayat mile jaane kab hi tumhen</span><span class=\"line\">Mu'azzin to ab bhi azaan dete hain</span></div>","<div class=\"verse\"><span class=\"line\">Kiraae pe rahte the khud jo kabhi</span><span class=\"line\">Kiraae pe ab wo makaan dete hain</span></div>","<div class=\"verse\"><span class=\"line\">Mukarte nahin hum kisi haal par</span><span class=\"line\">Agar hum kisi ko zabaan dete hain</span></div>","<div class=\"verse\"><span class=\"line\">Khuda jaanta hai ki saabir hain hum</span><span class=\"line\">So haan roz-o-shab imtihaan dete hain</span></div>","<div class=\"verse\"><span class=\"line\">Teri chashm-e-girya ke dhoke sada</span><span class=\"line\">Bahut so ko dard-e-nihaan dete hain</span></div>","<div class=\"verse\"><span class=\"line\">Bhale mausamon mein bhi kaisa sukoon</span><span class=\"line\">Sabhi kuchh wo kar raaegaan dete hain</span></div>","<div class=\"verse\"><span class=\"line\">Karun khoobiyon ka agar zikr main</span><span class=\"line\">Gina wo meri khaamiyaan dete hain</span></div>"],"firstLineEn": "Hamin hain rifaaqat mein jaan dete hain"},{"id": "ghazal-40","num": 40,"kind": "Ghazal · #40","firstLine": "कभी भी ऐसा तो होना न था मुझको","versesHtml": ["<div class=\"verse\"><span class=\"line\">कभी भी ऐसा तो होना न था मुझको</span><span class=\"line\">जो अब तेरे न होने ने किया मुझको</span></div>","<div class=\"verse\"><span class=\"line\">कभी वो ज़ख़्म दिखता है भरा मुझको</span><span class=\"line\">कभी वो ज़ख़्म लगता है हरा मुझको</span></div>","<div class=\"verse\"><span class=\"line\">मैं आजिज़ भी क्यूँ आता ऐसे जीने से</span><span class=\"line\">जो आए रोज़ मरने में मज़ा मुझको</span></div>","<div class=\"verse\"><span class=\"line\">जब उस से मैंने पूछीं हसरतें उस की</span><span class=\"line\">रहा वो हसरतों से देखता मुझको</span></div>","<div class=\"verse\"><span class=\"line\">सुना है फ़ासलों से इश्क़ बढ़ता है</span><span class=\"line\">सो हाँ मंज़ूर है ये फ़ासला मुझको</span></div>","<div class=\"verse\"><span class=\"line\">वो जो एक फूल मुरझाया था इन हाथों</span><span class=\"line\">महक आती है उसकी जा-ब-जा मुझको</span></div>","<div class=\"verse\"><span class=\"line\">मुझे उस रहगुज़र पे छोड़ने वाले</span><span class=\"line\">दिखा कर खुश न थे वो रास्ता मुझको</span></div>"],"versesHtmlEn": ["<div class=\"verse\"><span class=\"line\">Kabhi bhi aisa to hona na tha mujhko</span><span class=\"line\">Jo ab tere na hone ne kiya mujhko</span></div>","<div class=\"verse\"><span class=\"line\">Kabhi wo zakhm dikhta hai bhara mujhko</span><span class=\"line\">Kabhi wo zakhm lagta hai hara mujhko</span></div>","<div class=\"verse\"><span class=\"line\">Main aajiz bhi kyun aata aise jeene se</span><span class=\"line\">Jo aae roz marne mein maza mujhko</span></div>","<div class=\"verse\"><span class=\"line\">Jab us se mainne poochhin hasraten us ki</span><span class=\"line\">Raha wo hasraton se dekhta mujhko</span></div>","<div class=\"verse\"><span class=\"line\">Suna hai faaslon se ishq badhta hai</span><span class=\"line\">So haan manzoor hai ye faasla mujhko</span></div>","<div class=\"verse\"><span class=\"line\">Wo jo ek phool murjhaaya tha in haathon</span><span class=\"line\">Mahak aati hai uski ja-ba-ja mujhko</span></div>","<div class=\"verse\"><span class=\"line\">Mujhe us rahguzar pe chhodne waale</span><span class=\"line\">Dikha kar khush na the wo raasta mujhko</span></div>"],"firstLineEn": "Kabhi bhi aisa to hona na tha mujhko"}];
